                    (true, Some(_)) => state.pick_hover_key = pick_key,
                    (true, None) => {
                        state.pick_hover_key = None;
                        state.local_hover_id = None;
                        state.local_hover_granularity_id = None;
                    }
                    (false, _) => {
                        state.local_hover_id = object.map(str::to_owned);
