struct WorldTerrainMeshCursor {
    surface_id: String,
    z: u32,
    x: u32,
    y: u32,
    payload: TerrainTileMeshPayload,
    generation: u64,
    source_revision: u64,
    terrain_revision: u64,
    phase: WorldTerrainMeshPhase,
    triangle: u32,
    vertex: u8,
    item: u32,
