    let groups: Vec<u32> = marquee.results.pages[0][..usize::from(marquee.results.lens[0])].iter().map(|result| match result.unwrap() { WorldMarqueeResult::Component { id, .. } => id, _ => panic!("original vertex component") }).collect();
