    /// 🌑 Encodes the fixed scene clear packet without traversing retained draw owners.
    pub fn clear_prepared_scene<'a>(&'a self, encoder: &mut wgpu::CommandEncoder, scene: &'a SceneColorTarget, depth_view: Option<&'a wgpu::TextureView>, clear: wgpu::Color) {
        let pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_scene_clear"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: scene.mip_view(0),
                resolve_target: None,
                ops: wgpu::Operations { load: wgpu::LoadOp::Clear(clear), store: wgpu::StoreOp::Store },
                depth_slice: None,
            })],
            depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Clear(1.0), wgpu::LoadOp::Clear(0))),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        drop(pass);
    }

    /// 🔹 Encodes one retained UI instance without collecting or traversing sibling layers.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_ui_scalar<'a>(
        &'a self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        raster_store: &'a RasterTextureTable,
        instance: &UiInstance,
        raster_key: Option<&str>,
        scissor: Option<ScissorRect>,
        width: f32,
        height: f32,
        time_seconds: f32,
    ) -> Result<(), &'static str> {
        self.update_globals(queue, width, height, time_seconds);
        let Some(buffer) = frame_buffers.ui_instances.upload(device, queue, std::slice::from_ref(instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_ui_scalar") else {
            return Err("prepared UI scalar buffer admission failed");
        };
        let bind_group = match raster_key {
            Some(key) => &raster_store.get(key).ok_or("prepared raster scalar texture was missing")?.bind_group,
            None => &self.glyph_bind_group,
        };
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_ui_scalar"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        set_pass_scissor(&mut pass, scissor, self.surface_scale, width, height);
        pass.set_pipeline(&self.ui_pipeline);
        pass.set_bind_group(0, bind_group, &[]);
        pass.set_vertex_buffer(0, self.quad_vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, buffer);
        pass.draw(0..6, 0..1);
        Ok(())
    }

    /// 🔺 Encodes one retained vector triangle without staging a dynamic batch.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_vector_triangle<'a>(
        &'a self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        vertices: &[VectorVertex],
        scissor: Option<ScissorRect>,
        width: f32,
        height: f32,
        time_seconds: f32,
    ) -> Result<(), &'static str> {
        if vertices.len() != 3 {
            return Err("prepared vector scalar was not one triangle");
        }
        self.update_globals(queue, width, height, time_seconds);
        let Some(buffer) = frame_buffers.vector_vertices.upload(device, queue, vertices, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_vector_triangle") else {
            return Err("prepared vector triangle buffer admission failed");
        };
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_vector_triangle"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        set_pass_scissor(&mut pass, scissor, self.surface_scale, width, height);
        pass.set_pipeline(&self.vector_pipeline);
        pass.set_bind_group(0, &self.glyph_bind_group, &[]);
        pass.set_vertex_buffer(0, buffer);
        pass.draw(0..3, 0..1);
        Ok(())
    }

    /// 🌑️ Clears the lazily enlarged directional depth map before this scene's bounded caster
    /// scalars. Disabled shadows leave the one-pixel fallback resident and issue no GPU work.
    pub fn encode_prepared_world_shadow_begin(&mut self, device: &wgpu::Device, encoder: &mut wgpu::CommandEncoder, pass_owner: &ScenePass3d) {
        if !pass_owner.shadow.enabled {
            return;
        }
        if self.world_shadow_target.size != pass_owner.shadow.map_size {
            self.world_shadow_target = WorldShadowTarget::new(device, &self.world_shadow_bind_group_layout, pass_owner.shadow.map_size);
        }
        let _pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_shadow_clear"),
            color_attachments: &[],
            depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment { view: &self.world_shadow_target.view, depth_ops: Some(wgpu::Operations { load: wgpu::LoadOp::Clear(1.0), store: wgpu::StoreOp::Store }), stencil_ops: None }),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
    }

    /// 🌑️ Encodes one opaque caster into the scene's shadow map. One instance per call keeps
    /// cancellation and replacement at the same scalar boundary as the color pass.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_world_shadow_instance<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        frame_buffers: &'a mut FrameBuffers,
        mesh_store: &'a MeshGpuTable,
        pass_owner: &ScenePass3d,
        mesh_key: &str,
        mesh_version: u64,
        instance: &crate::wgpu::kernel_3d_scene::Instance3d,
    ) -> Result<bool, &'static str> {
        if !pass_owner.shadow.enabled {
            return Ok(false);
        }
        if self.world_shadow_target.size != pass_owner.shadow.map_size {
            return Err("prepared world shadow map was not begun");
        }
        let Some(mesh) = mesh_store.get_versioned(mesh_key, mesh_version) else { return Ok(false) };
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        let gpu_instance =
            World3dGpuInstance::from_instance(instance.model.to_cols_array_m(), instance.color, instance.material.preserve_vertex_color, instance.material.emissive_intensity, instance.material.metalness, instance.material.roughness, false);
        let Some(instance_buffer) = frame_buffers.world_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_shadow_instance") else {
            return Err("prepared world shadow instance buffer admission failed");
        };
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_shadow_instance"),
            color_attachments: &[],
            depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment { view: &self.world_shadow_target.view, depth_ops: Some(wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }), stencil_ops: None }),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_pipeline(&self.world_shadow_pipeline);
        pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
        pass.set_vertex_buffer(0, mesh.vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, instance_buffer);
        pass.set_index_buffer(mesh.index_buffer.slice(..), wgpu::IndexFormat::Uint32);
        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
        Ok(true)
    }

    /// 🌐 Encodes one retained mesh instance under one scene-pass owner, answering whether it drew.
    ///
    /// 🕰️ A mesh key/version that is not resident draws NOTHING and is not a fault, exactly as
    /// [`Self::encode_prepared_world_textured`] answers a raster whose pixels have not landed. A miss
    /// used to be a FATAL `present_step` fault that quarantined the whole surface for the rest of the
    /// session — one unbacked ghost draw killed the puzzle3d journey mid-flight (ticket
    /// 26/09/17/WGPU-RENDERER-REACT-PARITY, `📓️w11a-prepared-world-mesh-missing.md`). React simply
    /// renders nothing until its loader resolves, so the skip is the parity behaviour; the source-side
    /// residency law lives in `♾️infinite/🌍️world`'s `retain_ensured_world_draws`, and the skip is
    /// reported once per transition by the host so a regression there stays readable.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_world_instance<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        mesh_store: &'a MeshGpuTable,
        pass_owner: &ScenePass3d,
        mesh_key: &str,
        mesh_version: u64,
        instance: &crate::wgpu::kernel_3d_scene::Instance3d,
        receives_shadow: bool,
        translucent: bool,
        scissor: ScissorRect,
        width: f32,
        height: f32,
    ) -> Result<bool, &'static str> {
        let Some(mesh) = mesh_store.get_versioned(mesh_key, mesh_version) else { return Ok(false) };
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        let gpu_instance =
            World3dGpuInstance::from_instance(instance.model.to_cols_array_m(), instance.color, instance.material.preserve_vertex_color, instance.material.emissive_intensity, instance.material.metalness, instance.material.roughness, receives_shadow);
        let Some(instance_buffer) = frame_buffers.world_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_instance") else {
            return Err("prepared world instance buffer admission failed");
        };
        let scale = self.surface_scale;
        let viewport = pass_owner.viewport;
        let scene_scissor = self.physical_scissor(scissor);
        if scene_scissor.w == 0 || scene_scissor.h == 0 {
            return Ok(true);
        }
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_instance"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_viewport(viewport[0] * scale, viewport[1] * scale, viewport[2] * scale, viewport[3] * scale, 0.0, 1.0);
        pass.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        pass.set_pipeline(if translucent { &self.world_pipeline_translucent } else { &self.world_pipeline });
        pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
        pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
        pass.set_vertex_buffer(0, mesh.vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, instance_buffer);
        pass.set_index_buffer(mesh.index_buffer.slice(..), wgpu::IndexFormat::Uint32);
        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
        pass.set_viewport(0.0, 0.0, width * scale, height * scale, 0.0, 1.0);
        Ok(true)
    }

    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_world_material<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        mesh_store: &'a MeshGpuTable,
        raster_store: &'a RasterTextureTable,
        pass_owner: &ScenePass3d,
        draw_owner: &crate::wgpu::kernel_3d_scene::SceneMaterialDraw3d,
        instance: &crate::wgpu::kernel_3d_scene::Instance3d,
        scissor: ScissorRect,
        width: f32,
        height: f32,
    ) -> Result<bool, &'static str> {
        let Some(mesh) = mesh_store.get_versioned(&draw_owner.mesh_key, draw_owner.mesh_version) else { return Ok(false) };
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        let painted_bind_group;
        let instance_buffer = match &draw_owner.material {
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Standard => {
                painted_bind_group = None;
                let gpu_instance = World3dGpuInstance::from_instance(
                    instance.model.to_cols_array_m(),
                    instance.color,
                    instance.material.preserve_vertex_color,
                    instance.material.emissive_intensity,
                    instance.material.metalness,
                    instance.material.roughness,
                    pass_owner.shadow.enabled,
                );
                frame_buffers
                    .world_instances
                    .upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_standard_translucent")
                    .ok_or("prepared world standard translucent buffer admission failed")?
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Painted { texture_key } => {
                let Some(raster) = raster_store.get(texture_key) else { return Ok(true) };
                painted_bind_group = Some(device.create_bind_group(&wgpu::BindGroupDescriptor {
                    label: Some("world3d_painted_bind_group"),
                    layout: &self.scene_bind_group_layout,
                    entries: &[wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&raster.view) }, wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(&self.world_plane_sampler) }],
                }));
                let gpu_instance = World3dGpuInstance::from_instance(
                    instance.model.to_cols_array_m(),
                    instance.color,
                    instance.material.preserve_vertex_color,
                    instance.material.emissive_intensity,
                    instance.material.metalness,
                    instance.material.roughness,
                    pass_owner.shadow.enabled,
                );
                frame_buffers.world_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_painted").ok_or("prepared world painted buffer admission failed")?
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Celebration { stops, angle } => {
                painted_bind_group = None;
                let gpu_instance = World3dCelebrationGpuInstance::from_instance(instance.model.to_cols_array_m(), *stops, *angle, instance.color[3]);
                frame_buffers
                    .world_celebration_instances
                    .upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_celebration")
                    .ok_or("prepared world celebration buffer admission failed")?
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Authored(material) => {
                let keys = [&material.base_color_texture, &material.metallic_roughness_texture, &material.normal_texture, &material.occlusion_texture, &material.emissive_texture];
                painted_bind_group = if keys.iter().any(|key| key.is_some()) {
                    let mut entries = Vec::with_capacity(10);
                    for (role,key) in keys.into_iter().enumerate() {
                        let view = if let Some(key) = key { let Some(raster) = raster_store.get(key) else { return Ok(true) }; &raster.view } else { &self.world_authored_white };
                        let descriptor = if role == 0 { material.texture_sampler } else { material.additional_texture_samplers[role-1] };
                        let sampler = &self.world_material_samplers.iter().find(|(candidate,_)| *candidate == descriptor).ok_or("authored material sampler was not prepared")?.1;
                        entries.push(wgpu::BindGroupEntry { binding: role as u32 * 2, resource: wgpu::BindingResource::TextureView(view) });
                        entries.push(wgpu::BindGroupEntry { binding: role as u32 * 2 + 1, resource: wgpu::BindingResource::Sampler(sampler) });
                    }
                    Some(device.create_bind_group(&wgpu::BindGroupDescriptor { label: Some("world3d_authored_bind_group"), layout: &self.world_authored_bind_group_layout, entries: &entries }))
                } else { None };
                let gpu_instance = World3dGpuInstance::from_authored(instance.model.to_cols_array_m(), material, pass_owner.shadow.enabled);
                frame_buffers.world_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_authored").ok_or("prepared world authored buffer admission failed")?
            }
        };
        let scale = self.surface_scale;
        let viewport = pass_owner.viewport;
        let scene_scissor = self.physical_scissor(scissor);
        if scene_scissor.w == 0 || scene_scissor.h == 0 {
            return Ok(true);
        }
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_material"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_viewport(viewport[0] * scale, viewport[1] * scale, viewport[2] * scale, viewport[3] * scale, 0.0, 1.0);
        pass.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        match &draw_owner.material {
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Standard => {
                pass.set_pipeline(&self.world_standard_translucent_pipeline);
                pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
                pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Painted { .. } => {
                pass.set_pipeline(if draw_owner.translucent { &self.world_painted_pipeline_translucent } else { &self.world_painted_pipeline });
                pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
                pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
                pass.set_bind_group(2, painted_bind_group.as_ref().expect("painted branch owns its texture bind group"), &[]);
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Celebration { .. } => {
                pass.set_pipeline(if draw_owner.translucent { &self.world_celebration_pipeline_translucent } else { &self.world_celebration_pipeline });
                pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Authored(material) => {
                if painted_bind_group.is_some() {
                    pass.set_pipeline(match (draw_owner.translucent, material.double_sided) {
                        (false, false) => &self.world_authored_painted_front_pipeline,
                        (false, true) => &self.world_authored_painted_double_pipeline,
                        (true, false) => &self.world_authored_painted_front_translucent_pipeline,
                        (true, true) => &self.world_authored_painted_double_translucent_pipeline,
                    });
                    pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
                    pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
                    pass.set_bind_group(2, painted_bind_group.as_ref().expect("authored texture owns its bind group"), &[]);
                } else {
                    pass.set_pipeline(match (draw_owner.translucent, material.double_sided) {
                        (false, false) => &self.world_authored_front_pipeline,
                        (false, true) => &self.world_pipeline,
                        (true, false) => &self.world_pipeline_translucent,
                        (true, true) => &self.world_authored_double_translucent_pipeline,
                    });
                    pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
                    pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
                }
            }
        }
        pass.set_vertex_buffer(0, mesh.vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, instance_buffer);
        pass.set_index_buffer(mesh.index_buffer.slice(..), wgpu::IndexFormat::Uint32);
        let first = draw_owner.first_index.min(mesh.index_count);
        let end = first.saturating_add(draw_owner.index_count).min(mesh.index_count);
        if first < end {
            pass.draw_indexed(first..end, 0, 0..1);
        }
        pass.set_viewport(0.0, 0.0, width * scale, height * scale, 0.0, 1.0);
        Ok(true)
    }

    /// 🖼️ Encodes one retained TEXTURED world quad — the reference underlay — under one scene-pass
    /// owner.
    ///
    /// 🩸️ `ScenePass3d::textured_draws` has been measured by `advance_pipeline` and carried in every
    /// prepared packet since the scene pass existed, and `DrawMeasureCursor::PassTextured*` walked it
    /// page by page — but nothing ever ENCODED it: `encode_prepared_draw_scalar` had no arm for those
    /// cursors and `WORLD3D_TEXTURED_PIPELINE` was declared in the shader contract as "inferred —
    /// unwired in draw.rs". The plan underlay the puzzle3d playground decodes, admits and submits
    /// (`textured=1` on both surfaces) could therefore never paint on any target, ever
    /// (ticket 26/09/17/WGPU-RENDERER-REACT-PARITY packet W5c).
    ///
    /// 🕰️ A key whose pixels have not landed yet draws NOTHING and is not a fault: the underlay's
    /// instance is published the frame its url appears, long before the image is fetched and decoded,
    /// exactly as React returns `null` from `WorldReferencePlaneItem` until `media` resolves.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_world_textured<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        raster_store: &'a RasterTextureTable,
        pass_owner: &ScenePass3d,
        instance: &crate::wgpu::kernel_3d_scene::TexturedInstance3d,
        scissor: ScissorRect,
    ) -> Result<(), &'static str> {
        let Some(raster) = raster_store.get(&instance.texture_key) else { return Ok(()) };
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        let gpu_instance = World3dTexturedGpuInstance::from_instance(instance.model.to_cols_array_m(), instance.background, instance.appearance);
        let Some(instance_buffer) = frame_buffers.world_textured_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_textured") else {
            return Err("prepared world textured buffer admission failed");
        };
        let texture_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("world3d_textured_bind_group"),
            layout: &self.scene_bind_group_layout,
            entries: &[wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&raster.view) }, wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(&self.world_plane_sampler) }],
        });
        let scale = self.surface_scale;
        let viewport = pass_owner.viewport;
        let scene_scissor = self.physical_scissor(scissor);
        if scene_scissor.w == 0 || scene_scissor.h == 0 {
            return Ok(());
        }
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_textured"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_viewport(viewport[0] * scale, viewport[1] * scale, viewport[2] * scale, viewport[3] * scale, 0.0, 1.0);
        pass.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        pass.set_pipeline(&self.world_textured_pipeline);
        pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
        pass.set_bind_group(1, &texture_bind_group, &[]);
        pass.set_vertex_buffer(0, self.world_plane_vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, instance_buffer);
        pass.draw(0..6, 0..1);
        Ok(())
    }

    pub fn encode_prepared_world_grid<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        pass_owner: &ScenePass3d,
        scissor: ScissorRect,
    ) -> Result<(), &'static str> {
        let grid = pass_owner.procedural_grid.as_ref().ok_or("prepared world grid cursor was stale")?;
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        queue.write_buffer(&self.world_grid_uniform_buffer, 0, bytemuck::bytes_of(&World3dGridUniforms::from_grid(grid)));
        let viewport = physical_viewport_rect(pass_owner.viewport, self.surface_scale);
        let scene_scissor = self.physical_scissor(scissor);
        if scene_scissor.w == 0 || scene_scissor.h == 0 {
            return Ok(());
        }
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_grid"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_viewport(viewport[0], viewport[1], viewport[2], viewport[3], 0.0, 1.0);
        pass.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        pass.set_pipeline(&self.world_grid_pipeline);
        pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
        pass.set_bind_group(1, &self.world_grid_bind_group, &[]);
        pass.set_vertex_buffer(0, self.world_plane_vertex_buffer.slice(..));
        pass.draw(0..6, 0..1);
        Ok(())
    }

    /// 📏 Encodes one retained world line segment under one scene-pass owner.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_world_line<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        pass_owner: &ScenePass3d,
        vertices: &[crate::wgpu::kernel_3d_scene::LineVertex3d],
        scissor: ScissorRect,
    ) -> Result<(), &'static str> {
        if vertices.len() != 2 {
            return Err("prepared world line scalar was not one segment");
        }
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        let gpu_vertices = [WorldLineGpuVertex { position: vertices[0].position, color: vertices[0].color }, WorldLineGpuVertex { position: vertices[1].position, color: vertices[1].color }];
        let Some(line_buffer) = frame_buffers.world_lines.upload(device, queue, &gpu_vertices, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_line") else {
            return Err("prepared world line buffer admission failed");
        };
        let scale = self.surface_scale;
        let viewport = pass_owner.viewport;
        let scene_scissor = self.physical_scissor(scissor);
        if scene_scissor.w == 0 || scene_scissor.h == 0 {
            return Ok(());
        }
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_line"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_viewport(viewport[0] * scale, viewport[1] * scale, viewport[2] * scale, viewport[3] * scale, 0.0, 1.0);
        pass.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        pass.set_pipeline(&self.world_line_pipeline);
        pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
        pass.set_vertex_buffer(0, line_buffer);
        pass.draw(0..2, 0..1);
        Ok(())
    }

    /// 🎭️ Replays one completed World viewport through its image remap and physical viewport mask.
    pub fn encode_prepared_world_postprocess(
        &self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        composite: &PreparedCompositeTarget,
        pass_owner: &ScenePass3d,
        scene_scissor: ScissorRect,
    ) -> Result<(), &'static str> {
        let curvilinear = pass_owner.curvilinear;
        let ellipse = pass_owner.viewport_mask == crate::wgpu::kernel_3d_scene::SceneViewportMask3d::Ellipse;
        if curvilinear.is_none() && !ellipse {
            return Err("prepared world postprocess pass had no descriptor");
        }
        let background = if ellipse { composite.postprocess_background_view().ok_or("prepared ellipse background snapshot was missing")? } else { &composite.postprocess_scene_scratch_view };
        let scale = self.surface_scale;
        let viewport = [pass_owner.viewport[0] * scale, pass_owner.viewport[1] * scale, pass_owner.viewport[2] * scale, pass_owner.viewport[3] * scale];
        let fov_strength = curvilinear.map_or([0.0, 0.0], |value| [value.fov_radians, value.strength]);
        queue.write_buffer(
            &self.postprocess_globals_buffer,
            0,
            bytemuck::bytes_of(&WorldPostprocessGlobals { viewport, surface_size: [composite.width as f32, composite.height as f32], fov_strength, modes: [u32::from(curvilinear.is_some()), u32::from(ellipse), 0, 0], clear_color: [0.0; 4] }),
        );
        composite.copy_to_postprocess_scene_scratch(encoder);
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("prepared_world_postprocess_bind_group"),
            layout: &self.postprocess_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: self.postprocess_globals_buffer.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::TextureView(&composite.postprocess_scene_scratch_view) },
                wgpu::BindGroupEntry { binding: 2, resource: wgpu::BindingResource::Sampler(&composite.sampler) },
                wgpu::BindGroupEntry { binding: 3, resource: wgpu::BindingResource::TextureView(background) },
            ],
        });
        let mut render = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_postprocess"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: composite.world_encoded_view(), resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        render.set_viewport(viewport[0], viewport[1], viewport[2].max(1.0), viewport[3].max(1.0), 0.0, 1.0);
        let scene_scissor = self.physical_scissor(scene_scissor);
        render.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        render.set_pipeline(&self.world_postprocess_pipeline);
        render.set_bind_group(0, &bind_group, &[]);
        render.draw(0..6, 0..1);
        Ok(())
    }

    /// 🫧️ Paints an authored World background after the backdrop snapshot and before any 3D payload.
    pub fn encode_prepared_world_scene_clear(
        &self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        composite: &PreparedCompositeTarget,
        pass_owner: &ScenePass3d,
        scene_scissor: ScissorRect,
    ) -> Result<(), &'static str> {
        let clear_color = pass_owner.clear_color.ok_or("prepared world scene clear had no color")?;
        let background = composite.postprocess_background_view().ok_or("prepared world scene clear had no background snapshot")?;
        let scale = self.surface_scale;
        let viewport = [pass_owner.viewport[0] * scale, pass_owner.viewport[1] * scale, pass_owner.viewport[2] * scale, pass_owner.viewport[3] * scale];
        queue.write_buffer(
            &self.postprocess_globals_buffer,
            0,
            bytemuck::bytes_of(&WorldPostprocessGlobals { viewport, surface_size: [composite.width as f32, composite.height as f32], fov_strength: [0.0; 2], modes: [0, 0, 1, 0], clear_color }),
        );
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("prepared_world_scene_clear_bind_group"),
            layout: &self.postprocess_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: self.postprocess_globals_buffer.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::TextureView(background) },
                wgpu::BindGroupEntry { binding: 2, resource: wgpu::BindingResource::Sampler(&composite.sampler) },
                wgpu::BindGroupEntry { binding: 3, resource: wgpu::BindingResource::TextureView(background) },
            ],
        });
        let mut render = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_scene_clear"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: composite.world_encoded_view(), resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        render.set_viewport(viewport[0], viewport[1], viewport[2].max(1.0), viewport[3].max(1.0), 0.0, 1.0);
        let scene_scissor = self.physical_scissor(scene_scissor);
        render.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        render.set_pipeline(&self.world_postprocess_pipeline);
        render.set_bind_group(0, &bind_group, &[]);
        render.draw(0..6, 0..1);
        Ok(())
    }

    /// 🌫️ Builds one fixed blur mip for retained glass sampling.
    pub fn encode_prepared_blur_mip(&self, device: &wgpu::Device, queue: &wgpu::Queue, scene: &SceneColorTarget, mip: u32) -> Result<(), &'static str> {
        if mip == 0 || mip >= SCENE_MIP_LEVELS {
            return Err("prepared blur mip cursor was invalid");
        }
        let source = mip - 1;
        queue.write_buffer(&self.blur_globals_buffer, 0, bytemuck::bytes_of(&BlurGlobals { src_mip: 0.0, _pad: [0.0; 7] }));
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("prepared_blur_mip"),
            layout: &self.blur_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: self.blur_globals_buffer.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::TextureView(scene.blur_scratch_mip_view(source)) },
                wgpu::BindGroupEntry { binding: 2, resource: wgpu::BindingResource::Sampler(scene.sampler()) },
            ],
        });
        let mut copy = device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: Some("prepared_blur_copy") });
        scene.copy_mip_to_blur_scratch(&mut copy, source);
        queue.submit(Some(copy.finish()));
        let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: Some("prepared_blur_mip") });
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_blur_mip"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: scene.mip_view(mip),
                resolve_target: None,
                ops: wgpu::Operations { load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT), store: wgpu::StoreOp::Store },
                depth_slice: None,
            })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_pipeline(&self.blur_downsample_pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.draw(0..6, 0..1);
        drop(pass);
        queue.submit(Some(encoder.finish()));
        Ok(())
    }

    /// 🪟 Encodes one retained glass region after the scene snapshot is resident.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_glass_scalar<'a>(
        &'a self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        view: &'a wgpu::TextureView,
        scene: &'a SceneColorTarget,
        frame_buffers: &'a mut FrameBuffers,
        region: &GlassRegion,
        scissor: ScissorRect,
        width: f32,
        height: f32,
    ) -> Result<(), &'static str> {
        let instance = GlassInstance { rect: region.rect, tint: [region.tint.r, region.tint.g, region.tint.b, region.tint.a], params: [region.radius, region.alpha, Theme::glass_mip_level(region.blur_px, SCENE_MIP_LEVELS - 1), region.saturate] };
        let Some(buffer) = frame_buffers.glass_instances.upload(device, queue, std::slice::from_ref(&instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_glass_scalar") else {
            return Err("prepared glass scalar buffer admission failed");
        };
        let scene_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("prepared_glass_scene"),
            layout: &self.scene_bind_group_layout,
            entries: &[wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(scene.sample_view()) }, wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(scene.sampler()) }],
        });
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_glass_scalar"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        set_pass_scissor(&mut pass, Some(scissor), self.surface_scale, width, height);
        pass.set_pipeline(&self.glass_pipeline);
        pass.set_bind_group(0, &self.glyph_bind_group, &[]);
        pass.set_bind_group(1, &scene_bind_group, &[]);
        pass.set_vertex_buffer(0, self.quad_vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, buffer);
        pass.draw(0..6, 0..1);
        Ok(())
    }

    /// 🖼️ Encodes one fixed scene-to-surface packet after all command pages are resident.
    pub fn blit_prepared_scene<'a>(&'a self, device: &wgpu::Device, encoder: &mut wgpu::CommandEncoder, view: &'a wgpu::TextureView, scene: &'a SceneColorTarget) {
        self.blit_sampled_color(device, encoder, view, scene.sample_view(), scene.sampler());
    }

    /// 🖼️ Copies the accumulated composite into a backdrop snapshot or the terminal surface.
    pub fn blit_prepared_composite<'a>(&'a self, device: &wgpu::Device, encoder: &mut wgpu::CommandEncoder, view: &'a wgpu::TextureView, composite: &'a PreparedCompositeTarget) {
        self.blit_sampled_color(device, encoder, view, &composite.view, &composite.sampler);
    }

    #[allow(clippy::too_many_arguments, reason = "one arg per GPU resource/dimension; grouping into a struct is a T2 restructure, out of scope")]
    #[cfg(test)]
    pub fn render_scene_content<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        scene: &'a SceneColorTarget,
        depth_view: Option<&'a wgpu::TextureView>,
        draw: &DrawList,
        mesh_store: &MeshGpuTable,
        raster_store: &RasterTextureTable,
        frame_buffers: &mut FrameBuffers,
        width: f32,
        height: f32,
        time_seconds: f32,
    ) {
        self.update_globals(queue, width, height, time_seconds);
        let scene_view = scene.mip_view(0);
        let world_upload = if depth_view.is_some() { self.upload_world_passes(device, queue, draw, frame_buffers, LayerBatchFilter::Backdrop) } else { None };
        let (prepared_holder, pass_index_map) = match world_upload {
            Some((prepared, map)) => (Some(prepared), map),
            None => (None, vec![None; draw.scene_passes.len()]),
        };
        let world_prepared = prepared_holder.as_deref();
        let (all_ui, all_vec, batches) = build_layer_batches(draw, LayerBatchFilter::Backdrop);
        let (mask_data, mask_ranges) = build_batch_masks(&batches, width, height);
        let mask_buffer = frame_buffers.mask_instances.upload(device, queue, &mask_data, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "silhouette_masks");
        let ui_buffer = if all_ui.is_empty() { None } else { frame_buffers.ui_instances.upload(device, queue, &all_ui, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "ui_instances") };
        let vector_buffer = if all_vec.is_empty() { None } else { frame_buffers.vector_vertices.upload(device, queue, &all_vec, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "vector_vertices") };
        let instance_buffer = frame_buffers.world_instances.slice();
        let line_buffer = frame_buffers.world_lines.slice();
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("ui_pass"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: scene_view,
                resolve_target: None,
                ops: wgpu::Operations { load: wgpu::LoadOp::Clear(wgpu::Color { r: 0.05, g: 0.05, b: 0.06, a: 1.0 }), store: wgpu::StoreOp::Store },
                depth_slice: None,
            })],
            depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Clear(1.0), wgpu::LoadOp::Clear(0))),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        self.render_interleaved_layers(
            &mut pass,
            draw,
            &batches,
            mask_buffer.as_ref(),
            &mask_ranges,
            ui_buffer.as_ref(),
            vector_buffer.as_ref(),
            world_prepared,
            &pass_index_map,
            instance_buffer,
            line_buffer,
            mesh_store,
            width,
            height,
            depth_view.is_some(),
        );
        drop(pass);
        if draw.layers.iter().any(|layer| layer_matches_filter(layer, LayerBatchFilter::Backdrop) && !layer.raster_instances.is_empty()) {
            let mut raster_pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("ui_raster_pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: scene_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
                depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Load, wgpu::LoadOp::Clear(0))),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            self.draw_raster_layers(&mut raster_pass, raster_store, draw, frame_buffers, device, queue, width, height, LayerBatchFilter::Backdrop, false);
        }
        let (overlay_ui, overlay_vec, overlay_batches) = build_overlay_layer_batches(draw, LayerBatchFilter::Backdrop);
        if !overlay_ui.is_empty() || !overlay_vec.is_empty() {
            let (overlay_mask_data, overlay_mask_ranges) = build_batch_masks(&overlay_batches, width, height);
            let overlay_mask_buffer = frame_buffers.mask_instances.upload(device, queue, &overlay_mask_data, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "overlay_silhouette_masks");
            let overlay_ui_buffer = if overlay_ui.is_empty() { None } else { frame_buffers.ui_instances.upload(device, queue, &overlay_ui, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "overlay_ui_instances") };
            let overlay_vector_buffer = if overlay_vec.is_empty() { None } else { frame_buffers.vector_vertices.upload(device, queue, &overlay_vec, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "overlay_vector_vertices") };
            let mut overlay_pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("ui_overlay_pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: scene_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
                depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Load, wgpu::LoadOp::Clear(0))),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            self.render_interleaved_layers(
                &mut overlay_pass,
                draw,
                &overlay_batches,
                overlay_mask_buffer.as_ref(),
                &overlay_mask_ranges,
                overlay_ui_buffer.as_ref(),
                overlay_vector_buffer.as_ref(),
                None,
                &[],
                None,
                None,
                mesh_store,
                width,
                height,
                depth_view.is_some(),
            );
        }
        if draw.layers.iter().any(|layer| layer_matches_filter(layer, LayerBatchFilter::Backdrop) && !layer.overlay_raster_instances.is_empty()) {
            let mut raster_pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("ui_overlay_raster_pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: scene_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
                depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Load, wgpu::LoadOp::Clear(0))),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            self.draw_raster_layers(&mut raster_pass, raster_store, draw, frame_buffers, device, queue, width, height, LayerBatchFilter::Backdrop, true);
        }
    }

    #[cfg(test)]
    fn has_glass_foreground(draw: &DrawList) -> bool {
        let layer_content = draw.layers.iter().any(|layer| {
            layer.foreground_of.is_some()
                && (!layer.ui_instances.is_empty()
                    || !layer.vector_vertices.is_empty()
                    || !layer.raster_instances.is_empty()
                    || !layer.overlay_ui_instances.is_empty()
                    || !layer.overlay_vector_vertices.is_empty()
                    || !layer.overlay_raster_instances.is_empty())
        });
        let scene_content = draw.scene_passes.iter().any(|pass| layer_matches_filter(&draw.layers[pass.layer_index], LayerBatchFilter::Foreground));
        layer_content || scene_content
    }

    #[allow(clippy::too_many_arguments, reason = "one arg per GPU resource/dimension; grouping into a struct is a T2 restructure, out of scope")]
    #[cfg(test)]
    fn render_glass_foreground<'a>(
        &'a mut self,
