function surfaceSample(attribute: WorldMeshAttribute, mesh: WorldMeshData, corner: number): unknown {
  const vertex = mesh.indices[corner]!;
  const domain = attribute.domain === "vertex" ? vertex : attribute.domain === "corner" ? corner : attribute.domain === "face" ? Math.floor(corner / 3) : -1;
  if (domain < 0) throw new Error("a directed edge attribute cannot shade a triangle");
  const sample = attribute.indices?.[domain] ?? (attribute.indices ? -1 : domain);
  if (!Number.isInteger(sample) || sample < 0 || sample >= attribute.values.length) throw new Error("surface attribute references an invalid sample");
  return attribute.values[sample];
}

function surfaceTuple(value: unknown, width: number, name: string): number[] {
  if (!Array.isArray(value) || value.length !== width || value.some(value => typeof value !== "number" || !Number.isFinite(value))) throw new Error(`${name} requires a finite ${width}-component tuple`);
  return value as number[];
}

function surfaceAttributes(mesh: WorldMeshData, semantic: WorldMeshAttribute["semantic"]): [string, WorldMeshAttribute][] {
  return Object.entries(mesh.attributes ?? {}).filter(([, attribute]) => attribute.semantic === semantic).sort(([a],[b]) => a < b ? -1 : a > b ? 1 : 0);
}

/** 🎨️ Builds authored draw samples while retaining triangle order and original picking identities. */
export function geometryFromMesh(mesh: WorldMeshData) {
  if (mesh.positions.length % 3 || mesh.indices.length % 3 || mesh.positions.some(value => !Number.isFinite(value)) || mesh.indices.some(value => !Number.isInteger(value) || value < 0 || value >= mesh.positions.length / 3)) throw new Error("surface mesh has invalid positions or triangle indices");
  const normal = surfaceAttributes(mesh,"normal")[0]?.[1];
  const color = surfaceAttributes(mesh,"color")[0]?.[1];
  const tangent=mesh.attributes?.tangent;
  const uv = surfaceAttributes(mesh,"uv");
  const channels = [normal,color,tangent,...uv.map(([,attribute])=>attribute)].filter((value):value is WorldMeshAttribute=>Boolean(value));
  for(const attribute of channels){
    const count=attribute.domain === "vertex" ? mesh.positions.length/3 : attribute.domain === "face" ? mesh.indices.length/3 : mesh.indices.length;
    if(!["vertex","corner","face"].includes(attribute.domain)||(attribute.indices?.length ?? attribute.values.length)!==count||attribute.indices?.some(index=>!Number.isInteger(index)||index<0||index>=attribute.values.length))throw new Error("surface attribute cardinality differs from its domain");
  }
  const geometry = new BufferGeometry();
  const expanded = channels.some(attribute=>attribute.domain !== "vertex");
  const corners = expanded ? mesh.indices.length : mesh.positions.length / 3;
  const positions = expanded ? mesh.indices.flatMap(vertex=>mesh.positions.slice(vertex*3,vertex*3+3)) : mesh.positions;
  geometry.setAttribute("position",new BufferAttribute(new Float32Array(positions),3));
  if (!expanded && mesh.indices.length) geometry.setIndex([...mesh.indices]);
  const bind = (name:string,attribute:WorldMeshAttribute|undefined,width:number,fallback:readonly number[]|undefined)=>{
    if (attribute) {
      const values:number[]=[];
      for(let index=0;index<corners;index++){
        const value=expanded ? surfaceSample(attribute,mesh,index) : attribute.values[attribute.indices?.[index] ?? index];
        const tuple=surfaceTuple(value,width,name);if(name === "normal" && tuple.every(value=>value === 0))throw new Error("surface normal cannot be zero");values.push(...tuple);
      }
      geometry.setAttribute(name,new BufferAttribute(new Float32Array(values),width));
    } else if (fallback?.length) {
      if (fallback.length !== mesh.positions.length/3*width) throw new Error(`${name} buffer cardinality differs from the vertex count`);
      const values=expanded ? mesh.indices.flatMap(vertex=>fallback.slice(vertex*width,vertex*width+width)) : fallback;
      geometry.setAttribute(name,new BufferAttribute(new Float32Array(values),width));
    }
  };
  try {
    bind("normal",normal,3,mesh.normals);
    bind("color",color,4,mesh.colors);
    bind("tangent",tangent,4,undefined);
    if(tangent){const values=geometry.getAttribute("tangent");for(let i=0;i<values.count;i++){if(values.getW(i)!==1 && values.getW(i)!==-1 || values.getX(i)===0 && values.getY(i)===0 && values.getZ(i)===0)throw new Error("surface tangent requires a nonzero direction and signed handedness");}}
    if (uv.length) uv.forEach(([name,attribute],index)=>{const declared=/^uv(\d+)?$/.exec(name);const set=declared ? Number(declared[1] ?? 0) : index;bind(set ? `uv${set}` : "uv",attribute,2,undefined);});
    else bind("uv",undefined,2,mesh.uvs);
    if (geometry.hasAttribute("uv") && !geometry.hasAttribute("uv1")) geometry.setAttribute("uv1",geometry.getAttribute("uv").clone());
    if (!geometry.hasAttribute("normal")) geometry.computeVertexNormals();
    return geometry;
  } catch(error) {geometry.dispose();throw error;}
}

type VertexPickData = {
  readonly geometry: BufferGeometry;
  readonly vertexIds: readonly number[];
};

function buildVertexPickData(mesh: WorldMeshData): VertexPickData | null {
  if (!mesh.vertexIds?.length) return null;
  const positions: number[] = [];
  const vertexIds: number[] = [];
  const emitted = new Set<number>();
  for (let index = 0; index < mesh.vertexIds.length; index += 1) {
    const id = mesh.vertexIds[index]!;
    if (id === 0xffff_ffff || emitted.has(id)) continue;
    emitted.add(id);
    vertexIds.push(id);
    positions.push(mesh.positions[index * 3]!, mesh.positions[index * 3 + 1]!, mesh.positions[index * 3 + 2]!);
  }
  if (!positions.length) return null;
  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new BufferAttribute(new Float32Array(positions), 3));
  return { geometry, vertexIds };
}

export type WorldMeshAppearance = {
  readonly materials: MeshStandardMaterial[];
  readonly textures: Map<string, Texture>;
  readonly urls: Set<string>;
  readonly listeners: Set<()=>void>;
  pending: number;
  fault?: string;
  closed: boolean;
};

/** 🖍️ Applies owned material coefficients using glTF alpha and color-space conventions. */
export function worldSurfaceMaterial(name:string,source:Record<string,unknown>,vertexColors:boolean):MeshStandardMaterial {
  const base=surfaceTuple(source.baseColor ?? [1,1,1,1],4,"baseColor");
  const emissive=surfaceTuple(source.emissive ?? [0,0,0],3,"emissive");
  const alpha=source.alphaMode ?? "OPAQUE";
  if (!["OPAQUE","MASK","BLEND"].includes(String(alpha))) throw new Error("surface material has an invalid alpha mode");
  const coefficient=(name:string,defaultValue:number,maximum=1)=>{const value=source[name]??defaultValue;if(typeof value!=="number"||!Number.isFinite(Math.fround(value))||value<0||value>maximum)throw new Error(`surface material ${name} requires a coefficient in [0,${maximum}]`);return value;};
  if(base.some(value=>value<0||value>1)||emissive.some(value=>value<0))throw new Error("surface color coefficients are outside their domain");
  const normalScale=surfaceTuple(Array.isArray(source.normalScale)?source.normalScale:[source.normalScale ?? 1,source.normalScale ?? 1],2,"normalScale");if(normalScale.some(value=>Math.abs(value)>3.4028234663852886e38))throw new Error("surface material normalScale requires finite coefficients");
  const occlusionStrength=coefficient("occlusionStrength",1);
  const coordinates=source.textureCoordinates;if(coordinates!==undefined && (typeof coordinates!=="object"||coordinates===null||Array.isArray(coordinates)||Object.entries(coordinates).some(([key,value])=>!["baseColorTexture","metallicRoughnessTexture","normalTexture","occlusionTexture","emissiveTexture"].includes(key)||!Number.isInteger(value)||(value as number)<0||(value as number)>63)))throw new Error("surface material has invalid UV selectors");
  const material=new MeshStandardMaterial({name,vertexColors,metalness:coefficient("metallic",1),roughness:coefficient("roughness",1),opacity:alpha === "OPAQUE" ? 1 : base[3],transparent:alpha === "BLEND",alphaTest:alpha === "MASK" ? coefficient("alphaCutoff",.5,3.4028234663852886e38) : 0,depthWrite:alpha !== "BLEND",side:source.doubleSided === true ? DoubleSide : FrontSide});
  material.color.setRGB(base[0]!,base[1]!,base[2]!);
  material.emissive.setRGB(emissive[0]!,emissive[1]!,emissive[2]!);
  material.normalScale.set(normalScale[0]!,normalScale[1]!);material.aoMapIntensity=occlusionStrength;
  const extra=[...new Set(Object.values((coordinates ?? {}) as Record<string,number>).filter(set=>set>3))].sort((a,b)=>a-b);
  if(extra.length){material.onBeforeCompile=shader=>{shader.vertexShader=extra.map(set=>`attribute vec2 uv${set};`).join("\n")+"\n"+shader.vertexShader;};material.customProgramCacheKey=()=>`surface-uv:${extra.join(",")}`;}
  return material;
}

function buildWorldMeshAppearance(mesh:WorldMeshData,geometry:BufferGeometry):WorldMeshAppearance|null {
  const assignments=surfaceAttributes(mesh,"material")[0]?.[1];
  if (!assignments && !Object.keys(mesh.materials ?? {}).length) return null;
  const appearance:WorldMeshAppearance={materials:[],textures:new Map(),urls:new Set(),listeners:new Set(),pending:0,closed:false};
  const names:string[]=[];
  try {
    for(let corner=0;corner<mesh.indices.length;corner+=3){
      const name=assignments ? surfaceSample(assignments,mesh,corner) : Object.keys(mesh.materials!)[0];
      if (typeof name !== "string" || !mesh.materials?.[name]) throw new Error("face material references an unowned material");
      let index=names.indexOf(name);
      if(index<0){index=names.length;names.push(name);appearance.materials.push(worldSurfaceMaterial(name,mesh.materials[name]!,geometry.hasAttribute("color")));}
      const previous=geometry.groups.at(-1);
      if(previous?.materialIndex===index) previous.count+=3;
      else geometry.addGroup(corner,3,index);
    }
    for(const [index,name] of names.entries()){
      const source=mesh.materials![name]!;const material=appearance.materials[index]!;
      for(const [field,roles,srgb] of [["baseColorTexture",["map"],true],["metallicRoughnessTexture",["metalnessMap","roughnessMap"],false],["normalTexture",["normalMap"],false],["occlusionTexture",["aoMap"],false],["emissiveTexture",["emissiveMap"],true]] as const){
        const id=source[field];if(id===undefined)continue;
        if(typeof id!=="string"||!mesh.textures?.[id])throw new Error(`${field} references an unowned texture`);
        const coordinates=source.textureCoordinates as Record<string,number>|undefined;const set=coordinates?.[field] ?? 0;
        if(!geometry.hasAttribute(set ? `uv${set}` : "uv"))throw new Error(`${field} references an absent UV set`);
        const sampler=(source.textureSamplers as Record<string,Record<string,number>>|undefined)?.[field] ?? {};
        if(Object.entries(sampler).some(([field,value])=>!({wrapS:[33071,33648,10497],wrapT:[33071,33648,10497],magFilter:[9728,9729],minFilter:[9728,9729,9984,9985,9986,9987]} as Record<string,number[]>)[field]?.includes(value)))throw new Error("surface material texture sampler is invalid");
        const owned=mesh.textures[id]!;const key=`${id}:${srgb ? "srgb" : "linear"}:${set}:${sampler.wrapS ?? 10497}:${sampler.wrapT ?? 10497}:${sampler.magFilter ?? 9729}:${sampler.minFilter ?? 9729}`;
        let texture=appearance.textures.get(key);
        if(!texture){
          if(!["image/png","image/jpeg"].includes(owned.mime)||owned.bytes.length>16_000_000||owned.bytes.some(value=>!Number.isInteger(value)||value<0||value>255))throw new Error("surface texture requires bounded owned PNG/JPEG bytes");
          texture=new Texture();texture.colorSpace=srgb ? SRGBColorSpace : NoColorSpace;texture.channel=set;texture.flipY=false;
          const wraps={33071:ClampToEdgeWrapping,33648:MirroredRepeatWrapping,10497:RepeatWrapping};const filters={9728:NearestFilter,9729:LinearFilter,9984:NearestMipmapNearestFilter,9985:LinearMipmapNearestFilter,9986:NearestMipmapLinearFilter,9987:LinearMipmapLinearFilter};
          texture.wrapS=wraps[(sampler.wrapS ?? 10497) as keyof typeof wraps];texture.wrapT=wraps[(sampler.wrapT ?? 10497) as keyof typeof wraps];texture.magFilter=filters[(sampler.magFilter ?? 9729) as 9728|9729];texture.minFilter=filters[(sampler.minFilter ?? 9729) as keyof typeof filters];appearance.textures.set(key,texture);
          if(typeof URL.createObjectURL==="function"){
            const url=URL.createObjectURL(new Blob([Uint8Array.from(owned.bytes)],{type:owned.mime}));appearance.urls.add(url);appearance.pending++;
            const target=texture;
            new TextureLoader().load(url,loaded=>{URL.revokeObjectURL(url);appearance.urls.delete(url);if(!appearance.closed){target.image=loaded.image;target.needsUpdate=true;appearance.pending--;for(const listener of appearance.listeners)listener();}loaded.dispose();},undefined,()=>{URL.revokeObjectURL(url);appearance.urls.delete(url);if(!appearance.closed){appearance.pending--;appearance.fault=`texture ${id} could not be decoded`;for(const listener of appearance.listeners)listener();}});
          }
        }
        for(const role of roles)material[role]=texture;
      }
    }
    return appearance;
  }catch(error){disposeWorldMeshAppearance(appearance);throw error;}
}

function disposeWorldMeshAppearance(appearance:WorldMeshAppearance):void {
  if(appearance.closed)return;appearance.closed=true;for(const listener of appearance.listeners)listener();appearance.listeners.clear();
  for(const material of appearance.materials)material.dispose();
  for(const texture of appearance.textures.values())texture.dispose();
  for(const url of appearance.urls)URL.revokeObjectURL(url);appearance.urls.clear();
}

/** 🧊️ One existing mesh visual lease owns every draw buffer, material and decoded texture. */
export type MeshVisuals = { readonly record:WorldMeshRecord;readonly geometry:BufferGeometry|null;readonly border:EdgesGeometry|null;readonly vertexPick:VertexPickData|null;readonly edge:BufferGeometry|null;readonly appearance:WorldMeshAppearance|null;readonly fault?:string;closed:boolean; };

/** 🧊️ Builds authored visuals at the existing retained record boundary. */
export function buildMeshVisuals(record:WorldMeshRecord):MeshVisuals {
  if(!record.data)return {record,geometry:null,border:null,vertexPick:null,edge:null,appearance:null,closed:false};
  const geometry=geometryFromMesh(record.data);
  let border:EdgesGeometry|null=null;let vertexPick:VertexPickData|null=null;let edge:BufferGeometry|null=null;let appearance:WorldMeshAppearance|null=null;
  try {appearance=buildWorldMeshAppearance(record.data,geometry);border=new EdgesGeometry(geometry);vertexPick=buildVertexPickData(record.data);edge=buildEdgeGeometry(record.data);return {record,geometry,border,vertexPick,edge,appearance,closed:false};}
  catch(error){geometry.dispose();border?.dispose();vertexPick?.geometry.dispose();edge?.dispose();if(appearance)disposeWorldMeshAppearance(appearance);throw error;}
}

/** 🧹️ Retires each visual-owned resource exactly once; loader-shared GLB assets remain owned by their loader. */
export function disposeMeshVisuals(visuals:MeshVisuals):void {
  if(visuals.closed)return;visuals.closed=true;
  visuals.geometry?.dispose();visuals.border?.dispose();visuals.vertexPick?.geometry.dispose();visuals.edge?.dispose();
  if(visuals.appearance)disposeWorldMeshAppearance(visuals.appearance);
}

function buildEdgeGeometry(mesh: WorldMeshData): BufferGeometry | null {
  if (!mesh.edgePositions?.length) return null;
  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new BufferAttribute(new Float32Array(mesh.edgePositions), 3));
  return geometry;
}

/** 🧵️ Curve/centerline meshes have edge samples but no shaded triangles — pick/hover must treat them as whole instances. */
export function isCurveOnlyWorldMesh(mesh: Pick<WorldMeshData, "indices" | "edgePositions">): boolean {
  return Boolean(mesh.edgePositions?.length) && !(mesh.indices?.length > 0);
}

function buildFaceOverlayGeometry(mesh: WorldMeshData, faceIds: ReadonlySet<number>): BufferGeometry | null {
  if (!mesh.faceIds?.length || !mesh.indices.length || faceIds.size === 0) return null;
  const positions: number[] = [];
  const normals: number[] = [];
  for (let faceIndex = 0; faceIndex < mesh.faceIds.length; faceIndex += 1) {
    const faceId = mesh.faceIds[faceIndex]!;
    if (!faceIds.has(faceId)) continue;
    const i0 = mesh.indices[faceIndex * 3] ?? 0;
    const i1 = mesh.indices[faceIndex * 3 + 1] ?? 0;
    const i2 = mesh.indices[faceIndex * 3 + 2] ?? 0;
    for (const index of [i0, i1, i2]) {
      positions.push(mesh.positions[index * 3]!, mesh.positions[index * 3 + 1]!, mesh.positions[index * 3 + 2]!);
      normals.push(mesh.normals[index * 3]!, mesh.normals[index * 3 + 1]!, mesh.normals[index * 3 + 2]!);
    }
  }
  if (!positions.length) return null;
  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new BufferAttribute(new Float32Array(positions), 3));
  geometry.setAttribute("normal", new BufferAttribute(new Float32Array(normals), 3));
  return geometry;
}

/** 🖱️➡️ Approximates a picked face's in-plane size from its triangles' local bounding box, dropping the
 * smallest axis (roughly the one aligned with the face normal for axis-aligned primitive faces) — good
 * enough to size a push/pull tool's footprint without needing a true tangent-plane projection. */
function faceExtentFromMesh(mesh: WorldMeshData, faceId: number): readonly [number, number] | undefined {
  if (!mesh.faceIds?.length || !mesh.indices.length) return undefined;
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  let minZ = Infinity;
  let maxZ = -Infinity;
  let found = false;
  for (let faceIndex = 0; faceIndex < mesh.faceIds.length; faceIndex += 1) {
    if (mesh.faceIds[faceIndex] !== faceId) continue;
    found = true;
    for (const corner of [0, 1, 2]) {
      const vertexIndex = mesh.indices[faceIndex * 3 + corner];
      if (vertexIndex == null) continue;
      const x = mesh.positions[vertexIndex * 3] ?? 0;
      const y = mesh.positions[vertexIndex * 3 + 1] ?? 0;
      const z = mesh.positions[vertexIndex * 3 + 2] ?? 0;
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);
      minZ = Math.min(minZ, z);
      maxZ = Math.max(maxZ, z);
    }
  }
  if (!found) return undefined;
  const extents = [maxX - minX, maxY - minY, maxZ - minZ].sort((a, b) => b - a);
  return [extents[0] ?? 0.2, extents[1] ?? 0.2];
}

function buildEdgeOverlayGeometry(mesh: WorldMeshData, edgeIds: ReadonlySet<number>): BufferGeometry | null {
  if (!mesh.edgeIds?.length || !mesh.edgePositions?.length || edgeIds.size === 0) return null;
  const positions: number[] = [];
  for (let edgeIndex = 0; edgeIndex < mesh.edgeIds.length; edgeIndex += 1) {
    if (!edgeIds.has(mesh.edgeIds[edgeIndex]!)) continue;
    const base = edgeIndex * 6;
    positions.push(mesh.edgePositions[base]!, mesh.edgePositions[base + 1]!, mesh.edgePositions[base + 2]!, mesh.edgePositions[base + 3]!, mesh.edgePositions[base + 4]!, mesh.edgePositions[base + 5]!);
  }
  if (!positions.length) return null;
  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new BufferAttribute(new Float32Array(positions), 3));
  return geometry;
}

function buildVertexOverlayGeometry(mesh: WorldMeshData, vertexIds: ReadonlySet<number>): BufferGeometry | null {
  const pick = buildVertexPickData(mesh);
  if (!pick) return null;
  const positions: number[] = [];
  for (let index = 0; index < pick.vertexIds.length; index += 1) {
    if (!vertexIds.has(pick.vertexIds[index]!)) continue;
    positions.push(pick.geometry.attributes.position!.getX(index), pick.geometry.attributes.position!.getY(index), pick.geometry.attributes.position!.getZ(index));
  }
  if (!positions.length) return null;
  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new BufferAttribute(new Float32Array(positions), 3));
  return geometry;
}

function paintTextureUrl(base64: string): string {
  return `data:image/png;base64,${base64}`;
}

function PaintTexturedMesh({
  geometry,
  style,
  styleKind,
  textureBase64,
  appearance,
  flatShading,
  children,
  ...meshProps
}: {
  readonly geometry: BufferGeometry;
  readonly style: MeshStyleColors;
  readonly styleKind: MeshStyleKind;
  readonly textureBase64?: string;
  readonly appearance?: WorldMeshAppearance | null;
  readonly flatShading?: boolean;
  readonly children?: React.ReactNode;
} & ComponentProps<"mesh">) {
  const paintMap = textureBase64 ? useLoader(TextureLoader, paintTextureUrl(textureBase64)) : null;
  const invalidate=useThree(state=>state.invalidate);
  useSyncExternalStore(useCallback(listener=>{appearance?.listeners.add(listener);return ()=>appearance?.listeners.delete(listener);},[appearance]),()=>`${appearance?.pending ?? 0}:${appearance?.fault ?? ""}:${appearance?.closed ?? false}`,()=>"0::false");
  useEffect(()=>{if(!appearance)return;const listener=()=>invalidate();appearance.listeners.add(listener);return ()=>{appearance.listeners.delete(listener);};},[appearance,invalidate]);
  const authored=appearance && !appearance.closed && (styleKind === "neutral" || styleKind === "disabled");
  // Per-vertex colours (energy class swatches, FEM contours) multiply against the material `color` in
  // three.js — white lets them show through in the neutral/disabled styles only. Selected/hovered paint
  // must match url-backed meshes (puzzle 3d, cad): solid token fill + emissive, not a guest-side bake.
  const hasVertexColors = geometry.hasAttribute("color");
  const preserveVertexColors = hasVertexColors && (styleKind === "neutral" || styleKind === "disabled");
  const celebrating = styleKind === "celebrated" && !preserveVertexColors;
  return (
    <mesh geometry={geometry} {...meshProps}>
      {authored ? <primitive object={appearance.materials} attach="material" dispose={null} /> : celebrating ? (
        <CelebratingConicMaterial opacity={style.opacity} />
      ) : (
        <meshStandardMaterial
          key={worldMeshMaterialRevision(styleKind)}
          color={preserveVertexColors ? "#ffffff" : style.meshColor}
          vertexColors={preserveVertexColors}
          map={paintMap ?? undefined}
          side={DoubleSide}
          flatShading={flatShading}
          metalness={0}
          roughness={1}
          emissive={preserveVertexColors ? "#000000" : style.meshColor}
          emissiveIntensity={preserveVertexColors ? 0 : style.emissiveIntensity}
          transparent={style.opacity < 1}
          opacity={style.opacity}
        />
      )}
      {children}
    </mesh>
  );
}

//#region GlbMeshBounds
/** 📦️ Local-space extents of every GLB the scene has loaded, keyed by the mesh record's own
 * `url` and already carrying the {@link GLB_MESH_FRAME_ROTATION_X} frame rotation the instance group
 * applies — so an entry is exactly the eight local corners a pick or a marquee has to project.
 *
 * 🎯️ A URL-backed mesh record carries NO inline `data` (the guest publishes `{id, url}` for every
 * catalogue representation), so every screen-space hit test over it used to fall back to a unit cube —
 * or, in the marquee's case, to the single point `[0,0,0]`. Measured on the 180-object Nakagin tower,
 * fully rendered: `candidates=180 containing=0 hit=none boxes=["28x30@427,394", …]` on 20 of 20 clicks
 * spread over the whole pane, while R3F's own raycast against the same GLB geometry resolved an
 * instance on 14 of them (26/09/02/PUZZLE-3D-END-TO-END wave B46). The loader is the only place that
 * knows a GLB's real size, so it is the place that records it. */
const GLB_MESH_LOCAL_BOUNDS = new Map<string, readonly (readonly [number, number, number])[]>();

/** 📦️ The eight corners of one loaded GLB's frame-rotated AABB, in the instance group's local space. */
function glbMeshFrameCorners(scene: Object3D): readonly (readonly [number, number, number])[] {
  const frame = new Object3D();
  frame.rotation.x = GLB_MESH_FRAME_ROTATION_X;
  frame.updateMatrixWorld(true);
  scene.updateMatrixWorld(true);
  const box = new Box3().setFromObject(scene);
  if (box.isEmpty()) return [];
  const scratch = new Vector3();
  const rotated = new Box3().makeEmpty();
  for (const corner of [
    [box.min.x, box.min.y, box.min.z],
    [box.max.x, box.min.y, box.min.z],
    [box.min.x, box.max.y, box.min.z],
    [box.max.x, box.max.y, box.min.z],
    [box.min.x, box.min.y, box.max.z],
    [box.max.x, box.min.y, box.max.z],
    [box.min.x, box.max.y, box.max.z],
    [box.max.x, box.max.y, box.max.z],
  ] as const) {
    rotated.expandByPoint(scratch.set(corner[0], corner[1], corner[2]).applyMatrix4(frame.matrixWorld));
  }
  return [
    [rotated.min.x, rotated.min.y, rotated.min.z],
    [rotated.max.x, rotated.min.y, rotated.min.z],
    [rotated.min.x, rotated.max.y, rotated.min.z],
    [rotated.max.x, rotated.max.y, rotated.min.z],
    [rotated.min.x, rotated.min.y, rotated.max.z],
    [rotated.max.x, rotated.min.y, rotated.max.z],
    [rotated.min.x, rotated.max.y, rotated.max.z],
    [rotated.max.x, rotated.max.y, rotated.max.z],
  ];
}

/** 📦️ The local corners a screen-space hit test must use for one instance's mesh: the mesh's own inline
 * geometry when it has some, else the loaded GLB's recorded extents, else — only while a GLB is still
 * loading — the unit cube. */
export function world3dInstanceLocalCorners(
  meshData: WorldMeshData | undefined,
  meshUrl: string | undefined,
  bounds: ReadonlyMap<string, readonly (readonly [number, number, number])[]> = GLB_MESH_LOCAL_BOUNDS,
): readonly (readonly [number, number, number])[] {
  if (meshData && (meshData.positions.length >= 3 || (meshData.edgePositions?.length ?? 0) >= 3)) return meshBoundsCorners(meshData);
  const recorded = meshUrl ? bounds.get(meshUrl) : undefined;
  if (recorded && recorded.length === 8) return recorded;
  return [
    [-0.5, -0.5, -0.5],
    [0.5, -0.5, -0.5],
    [-0.5, 0.5, -0.5],
    [0.5, 0.5, -0.5],
    [-0.5, -0.5, 0.5],
    [0.5, -0.5, 0.5],
    [-0.5, 0.5, 0.5],
    [0.5, 0.5, 0.5],
  ];
}
//#endregion GlbMeshBounds

//#region GlbMeshStyling
/** 🎨️ EdgesGeometry cache keyed by source BufferGeometry — `gltf.scene.clone(true)` shares geometries across every per-instance clone of the same GLB, so this dedupes edge computation across instances. */
const GLB_EDGE_GEOMETRY_CACHE = new WeakMap<BufferGeometry, EdgesGeometry>();

/** 🎨️ Adds a border-color {@link EdgesGeometry} outline to every mesh under `root` (idempotent), using the shared {@link GLB_EDGE_GEOMETRY_CACHE}. */
function applyGlbMeshEdgeBorders(root: Object3D, borderColor: string): void {
  // 🧵️ Collect targets before mutating: `object.add(...)` during `traverse()` would splice the new
  // (itself a Mesh) child into the live `children` array traverse is still walking, so it gets visited
  // and outlined again — and again — recursing until the stack overflows.
  const targets: Mesh[] = [];
  root.traverse((object) => {
    if (!(object instanceof Mesh)) return;
    const geometry = object.geometry;
    if (!geometry || object.children.some((child) => child.userData[WORLD_MESH_OUTLINE_USER_DATA_KEY])) return;
    targets.push(object);
  });
  for (const object of targets) {
    let edges = GLB_EDGE_GEOMETRY_CACHE.get(object.geometry);
    if (!edges) {
      edges = new EdgesGeometry(object.geometry);
      GLB_EDGE_GEOMETRY_CACHE.set(object.geometry, edges);
    }
    const outline = new LineSegments(edges, new LineBasicMaterial({ color: new Color(borderColor) }));
    outline.userData[WORLD_MESH_OUTLINE_USER_DATA_KEY] = true;
    outline.scale.setScalar(1.001);
    object.add(outline);
  }
}

//#endregion GlbMeshStyling

/** 🎭️ Clones authored materials for neutral styles and applies reversible active selection paint. */
export function cloneWorldGlbSurface(source:Object3D,revision:MeshStyleKind,style:{meshColor:string;emissiveIntensity:number;opacity:number},emissive=style.meshColor):Object3D {
  const cloned=source.clone(true);const owned=new Set<MeshStandardMaterial|ShaderMaterial>();const retained=new Map<object,MeshStandardMaterial>();const textures=new Map<Texture,Map<string,Texture>>();const geometries=new Set<BufferGeometry>();
  cloned.userData.semioOwnedSurfaceMaterials=owned;cloned.userData.semioOwnedSurfaceGeometries=geometries;
  try {cloned.traverse(child=>{
    if(!(child instanceof Mesh))return;
    if(revision === "neutral" || revision === "disabled"){
      const clone=(material:MeshStandardMaterial)=>{
        let result=retained.get(material);
        if(!result){
          result=material.clone();retained.set(material,result);owned.add(result);
          for(const role of ["map","metalnessMap","roughnessMap","normalMap","aoMap","emissiveMap"] as const){
            const texture=material[role];if(!texture)continue;
            const colorSpace=role === "map" || role === "emissiveMap" ? SRGBColorSpace : NoColorSpace;
            let roles=textures.get(texture);if(!roles){roles=new Map();textures.set(texture,roles);}
            let mapped=roles.get(colorSpace);if(!mapped){mapped=texture.clone();mapped.colorSpace=colorSpace;mapped.needsUpdate=true;roles.set(colorSpace,mapped);}result[role]=mapped;
          }
          const extra=[...new Set(["map","metalnessMap","roughnessMap","normalMap","aoMap","emissiveMap"].map(role=>(result as unknown as Record<string,Texture|null>)[role]?.channel ?? 0).filter(set=>set>3))].sort((a,b)=>a-b);
          if(extra.length){result.onBeforeCompile=shader=>{shader.vertexShader=extra.map(set=>`attribute vec2 uv${set};`).join("\n")+"\n"+shader.vertexShader;};result.customProgramCacheKey=()=>`surface-uv:${extra.join(",")}`;}
        }
        return result;
      };
      child.material=Array.isArray(child.material) ? child.material.map(clone) : clone(child.material as MeshStandardMaterial);
      const coordinates=[...new Set((Array.isArray(child.material)?child.material:[child.material]).flatMap(material=>["map","metalnessMap","roughnessMap","normalMap","aoMap","emissiveMap"].flatMap(role=>{const texture=(material as unknown as Record<string,Texture|null>)[role];return texture?[texture.channel]:[];})))];
      const missing=coordinates.filter(set=>!child.geometry.hasAttribute(set?`uv${set}`:"uv"));
      if(missing.length){const geometry=child.geometry.clone();for(const set of missing){const attribute=geometry.getAttribute(`texcoord_${set}`);if(!attribute){geometry.dispose();throw new Error("GLB texture references an absent UV set");}geometry.setAttribute(set?`uv${set}`:"uv",attribute);}child.geometry=geometry;geometries.add(geometry);}

    }else{
      const material=revision === "celebrated" ? createCelebratingConicMaterial(style.opacity) : new MeshStandardMaterial({color:new Color(style.meshColor),emissive:new Color(emissive),emissiveIntensity:style.emissiveIntensity,metalness:0,roughness:1,transparent:style.opacity<1,opacity:style.opacity});
      child.material=material;owned.add(material);
    }
  });}catch(error){cloned.userData.semioOwnedSurfaceTextures=new Set([...textures.values()].flatMap(roles=>[...roles.values()]));disposeWorldGlbSurface(cloned);throw error;}
  cloned.userData.semioOwnedSurfaceTextures=new Set([...textures.values()].flatMap(roles=>[...roles.values()]));
  return cloned;
}

/** 🧹️ Releases clone-owned material/chrome resources while preserving loader-owned geometry and textures. */
export function disposeWorldGlbSurface(scene:Object3D):void {
  const materials=scene.userData.semioOwnedSurfaceMaterials as Set<MeshStandardMaterial|ShaderMaterial>|undefined;
  if(!materials)return;for(const material of materials)material.dispose();materials.clear();delete scene.userData.semioOwnedSurfaceMaterials;
  const geometries=scene.userData.semioOwnedSurfaceGeometries as Set<BufferGeometry>|undefined;for(const geometry of geometries??[])geometry.dispose();geometries?.clear();delete scene.userData.semioOwnedSurfaceGeometries;
  const textures=scene.userData.semioOwnedSurfaceTextures as Set<Texture>|undefined;for(const texture of textures??[])texture.dispose();textures?.clear();delete scene.userData.semioOwnedSurfaceTextures;
  scene.traverse(child=>{if(child instanceof LineSegments && child.userData[WORLD_MESH_OUTLINE_USER_DATA_KEY]){const material=child.material;for(const owned of Array.isArray(material)?material:[material])owned.dispose();}});
}

function GlbInstanceMesh({
  url,
  color,
  emissive,
  emissiveIntensity,
  opacity,
  borderColor,
  material,
  shadowEnabled,
  revision,
  pickEnabled,
}: {
  readonly url: string;
  readonly color: string;
  readonly emissive: string;
  readonly emissiveIntensity: number;
  readonly opacity: number;
  readonly borderColor: string;
  readonly material?: WorldEnvironmentMaterialRecord;
  readonly shadowEnabled?: boolean;
  readonly revision: MeshStyleKind;
  readonly pickEnabled: boolean;
}) {
  const gltf = useLoader(GLTFLoader, publishedPageUrl(meshAssetTransportUrl(url, MESH_DELIVERY_CATALOG)));
  const invalidate = useThree((state) => state.invalidate);
  if (!GLB_MESH_LOCAL_BOUNDS.has(url)) {
    const corners = glbMeshFrameCorners(gltf.scene);
    if (corners.length === 8) GLB_MESH_LOCAL_BOUNDS.set(url, corners);
  }
  const celebrating = revision === "celebrated";
  // 🎨️ Bake selection/hover paint into the clone itself. Imperative `color.set` after deselect was leaving
  // the previous selected tint until a later hover remounted materials — style deps must recreate the tree.
  const scene = useMemo(() => {
    const cloned=cloneWorldGlbSurface(gltf.scene,revision,{meshColor:color,emissiveIntensity,opacity},emissive);
    cloned.traverse(child=>{if(child instanceof Mesh){child.castShadow=shadowEnabled===true;child.receiveShadow=shadowEnabled===true;}});
    applyGlbMeshEdgeBorders(cloned, borderColor);
    return cloned;
  }, [gltf.scene, material?.metalness, material?.roughness, shadowEnabled, color, emissive, emissiveIntensity, opacity, borderColor, revision, celebrating]);
  useEffect(()=>()=>disposeWorldGlbSurface(scene),[scene]);
  useFrame(() => {
    if (!celebrating) return;
    const angle = celebrateConicAngleRadians();
    scene.traverse((child) => {
      if (!(child instanceof Mesh)) return;
      const mat = child.material;
      if (!(mat instanceof ShaderMaterial) || !mat.uniforms?.uAngle) return;
      mat.uniforms.uAngle.value = angle;
    });
    invalidate();
  });
  // 🎞️ Demand frameloop: useLoader / style remounts after the mount kick would otherwise leave transparent panes.
  useLayoutEffect(() => {
    invalidate();
  }, [invalidate, scene]);
  useLayoutEffect(() => {
    applyWorldInstanceMeshRaycast(scene, pickEnabled, Mesh.prototype.raycast);
  }, [scene, pickEnabled]);

  return (
    <group rotation={[GLB_MESH_FRAME_ROTATION_X, 0, 0]}>
      <primitive object={scene} />
    </group>
  );
}

function extractGlbCollisionMesh(gltf: Awaited<ReturnType<GLTFLoader["loadAsync"]>>): {
  readonly positions: number[];
  readonly indices: number[];
} {
  const frame = new Object3D();
  frame.rotation.x = GLB_MESH_FRAME_ROTATION_X;
  frame.updateMatrixWorld(true);
  const positions: number[] = [];
  const indices: number[] = [];
  let vertexOffset = 0;
  const scratch = new Vector3();
  gltf.scene.updateMatrixWorld(true);
  gltf.scene.traverse((child) => {
    if (!(child instanceof Mesh)) return;
    const geometry = child.geometry;
    const positionAttr = geometry.getAttribute("position");
    if (!positionAttr) return;
    const worldMatrix = frame.matrixWorld.clone().multiply(child.matrixWorld);
    for (let index = 0; index < positionAttr.count; index += 1) {
      scratch.fromBufferAttribute(positionAttr, index).applyMatrix4(worldMatrix);
      positions.push(scratch.x, scratch.y, scratch.z);
    }
    const indexAttr = geometry.index;
    if (indexAttr) {
      for (let index = 0; index < indexAttr.count; index += 1) {
        indices.push(indexAttr.getX(index) + vertexOffset);
      }
    } else {
      for (let index = 0; index < positionAttr.count; index += 3) {
        indices.push(vertexOffset + index, vertexOffset + index + 1, vertexOffset + index + 2);
      }
    }
    vertexOffset += positionAttr.count;
  });
  return { positions, indices };
}

/** 🥽️ Announces one loaded GLB's collision geometry to the guest. `revision` is the ONLY thing that
 * re-announces an already-loaded mesh: the GLB is `useLoader`-cached for the page's lifetime, so without
 * it the announcement happens exactly once per mount and a guest that lost the geometry (a restored
 * actor, whose mesh store is not part of any checkpoint) could never be told again — see
 * {@link Puzzle3dBrushMeshRegistry}. */
function BrushMeshRegistrar({ url, revision, onRegister }: { readonly url: string; readonly revision: number; readonly onRegister: (url: string, positions: number[], indices: number[]) => void }) {
  const gltf = useLoader(GLTFLoader, publishedPageUrl(meshAssetTransportUrl(url, MESH_DELIVERY_CATALOG)));
  useEffect(() => {
    const mesh = extractGlbCollisionMesh(gltf);
    if (mesh.positions.length === 0 || mesh.indices.length === 0) return;
    onRegister(url, mesh.positions, mesh.indices);
  }, [gltf, onRegister, revision, url]);
  return null;
}

/** 🥽️ One loaded GLB as the single welded geometry a tool run trace instance draws through, already in the
 * {@link GLB_MESH_FRAME_ROTATION_X} frame the instance group applies. */
function ToolRunTraceGlbGeometry({ url, onGeometry }: { readonly url: string; readonly onGeometry: (url: string, geometry: BufferGeometry | null) => void }) {
  const gltf = useLoader(GLTFLoader, publishedPageUrl(meshAssetTransportUrl(url, MESH_DELIVERY_CATALOG)));
  useEffect(() => {
    const mesh = extractGlbCollisionMesh(gltf);
    if (mesh.positions.length === 0 || mesh.indices.length === 0) return;
    const geometry = new BufferGeometry();
    geometry.setAttribute("position", new BufferAttribute(new Float32Array(mesh.positions), 3));
    geometry.setIndex(mesh.indices);
    geometry.computeVertexNormals();
    onGeometry(url, geometry);
    return () => {
      onGeometry(url, null);
      geometry.dispose();
    };
  }, [gltf, onGeometry, url]);
  return null;
}

/** ⏯️ Mounts the scene's `toolRunTrace` lane for this window: one instanced mesh per `(mesh, verdict)` batch,
 * each drawn through `meshesJson[mesh]` — inline mesh data directly, a GLB once it has loaded, a unit box
 * until then. Only meshes a resident `instance3d` record names are loaded.
 * @see ./⏯️tool-run-trace/🟦️.tsx */
function WorldToolRunTrace({ lane, meshes, trace, focus }: { readonly lane: string | null | undefined; readonly meshes: readonly WorldMeshRecord[]; readonly trace: { readonly store: ToolRunTraceRecordStore; readonly version: number }; readonly focus?: bigint | null }) {
  const inline = useMemo(() => meshes.map((mesh) => (mesh.data ? geometryFromMesh(mesh.data) : null)), [meshes]);
  useEffect(() => () => inline.forEach((geometry) => geometry?.dispose()), [inline]);
  const [loaded, setLoaded] = useState<ReadonlyMap<string, BufferGeometry>>(() => new Map());
  const onGeometry = useCallback((url: string, geometry: BufferGeometry | null) => {
    setLoaded((previous) => {
      const next = new Map(previous);
      if (geometry) next.set(url, geometry);
      else next.delete(url);
      return next;
    });
  }, []);
  const urls = useMemo(() => {
    const named = new Set<string>();
    for (const batch of trace.store.batches()) {
      const mesh = batch.family === "instance3d" && batch.count > 0 ? meshes[batch.index] : undefined;
      if (mesh?.url && !mesh.data) named.add(mesh.url);
    }
    return [...named];
  }, [meshes, trace.store, trace.version]);
  const geometryForMesh = useCallback((index: number) => inline[index] ?? loaded.get(meshes[index]?.url ?? "") ?? null, [inline, loaded, meshes]);
  return (
    <>
      {urls.map((url) => (
        <Suspense key={url} fallback={null}>
          <ToolRunTraceGlbGeometry url={url} onGeometry={onGeometry} />
        </Suspense>
      ))}
      <ToolRunTraceLayer lane={lane} store={trace} geometryForMesh={geometryForMesh} focus={focus} />
    </>
  );
}

/** 🎛️ True when `mode` is an explicit transform-gumball utility (`move`/`rotate`/`scale`/`transform`) — never treat a missing/unknown mode as move. */
export function isWorldTransformGumballMode(mode: string | undefined): boolean {
  return mode === "move" || mode === "rotate" || mode === "scale" || mode === "transform";
}

function gumballKindForTransformMode(transformMode: string | undefined, handleKind?: GumballHandleKind): "translate" | "rotate" | "scale" {
  if ((transformMode === "transform" || transformMode === "move") && handleKind != null) {
    return gumballHandleKindToTransformMode(handleKind);
  }
  if (transformMode === "rotate") return "rotate";
  if (transformMode === "scale") return "scale";
  return "translate";
}

const GUMBALL_TRANSFORM_EPSILON = 1e-6;

/** 📍️ Vertex-granularity pick dots and their hover/selection marks, in CSS pixels (screen-space). */
const WORLD_VERTEX_DOT_PX = 6;
const WORLD_VERTEX_MARK_PX = 11;

/** 🧷️ Copies the plugin's opaque transform targets so a gesture keeps its initial selection. */
export function world3dGumballSelectionArgsV1(selection: {
  readonly ids?: readonly string[];
  readonly gumballSelectionIds?: readonly string[];
  readonly componentIds?: readonly number[];
  readonly selectionMode?: string;
  readonly granularity?: string;
}): { readonly mode: string; readonly ids: readonly string[] } {
  return { mode: selection.selectionMode ?? selection.granularity ?? "object", ids: [...(selection.gumballSelectionIds ?? selection.ids ?? [])] };
}

/** 🎛️ Builds one incremental `translateSelection` / `rotateSelection` / `scaleSelection` dispatch from consecutive gumball poses. */
export function gumballTransformDeltaBetweenPoses(
  transformMode: string | undefined,
  before: GumballPose,
  after: GumballPose,
  base: Record<string, unknown>,
  handleKind?: GumballHandleKind,
): { readonly action: string; readonly args: Record<string, unknown> } | null {
  const kind = gumballKindForTransformMode(transformMode, handleKind);
  if (kind === "translate") {
    const dx = after.position[0] - before.position[0];
    const dy = after.position[1] - before.position[1];
    const dz = after.position[2] - before.position[2];
    if (Math.abs(dx) < GUMBALL_TRANSFORM_EPSILON && Math.abs(dy) < GUMBALL_TRANSFORM_EPSILON && Math.abs(dz) < GUMBALL_TRANSFORM_EPSILON) {
      return null;
    }
    return { action: "translateSelection", args: { ...base, dx, dy, dz } };
  }
  if (kind === "rotate") {
    const beforeQuat = new Quaternion(...before.quaternion);
    const afterQuat = new Quaternion(...after.quaternion);
    const delta = afterQuat.multiply(beforeQuat.invert());
    const angle = 2 * Math.acos(Math.min(1, Math.max(-1, delta.w)));
    if (angle < GUMBALL_TRANSFORM_EPSILON) return null;
    const sinHalfAngle = Math.sqrt(Math.max(0, 1 - delta.w * delta.w));
    const axis = sinHalfAngle < 1e-6 ? { x: 0, y: 0, z: 1 } : { x: delta.x / sinHalfAngle, y: delta.y / sinHalfAngle, z: delta.z / sinHalfAngle };
    return { action: "rotateSelection", args: { ...base, ax: axis.x, ay: axis.y, az: axis.z, angle } };
  }
  const sx = after.scale[0] / Math.max(before.scale[0], GUMBALL_TRANSFORM_EPSILON);
  const sy = after.scale[1] / Math.max(before.scale[1], GUMBALL_TRANSFORM_EPSILON);
  const sz = after.scale[2] / Math.max(before.scale[2], GUMBALL_TRANSFORM_EPSILON);
  if (Math.abs(sx - 1) < GUMBALL_TRANSFORM_EPSILON && Math.abs(sy - 1) < GUMBALL_TRANSFORM_EPSILON && Math.abs(sz - 1) < GUMBALL_TRANSFORM_EPSILON) {
    return null;
  }
  return { action: "scaleSelection", args: { ...base, sx, sy, sz } };
}

/** 🛑️ The pose delta that moves nothing for a gumball handle kind — what a live gesture's `commit` carries when its
 * tail moved nothing, and the verb its `abort` names. */
export function gumballIdentityDelta(transformMode: string | undefined, base: Record<string, unknown>, handleKind?: GumballHandleKind): { readonly action: string; readonly args: Record<string, unknown> } {
  const kind = gumballKindForTransformMode(transformMode, handleKind);
  if (kind === "translate") return { action: "translateSelection", args: { ...base, dx: 0, dy: 0, dz: 0 } };
  if (kind === "rotate") return { action: "rotateSelection", args: { ...base, ax: 0, ay: 0, az: 1, angle: 0 } };
  return { action: "scaleSelection", args: { ...base, sx: 1, sy: 1, sz: 1 } };
}

/** 🖌️ Where a paint dab under the pointer comes from: the press that opens a paint gesture, a drag over a mesh while it is
 * held, or the click that follows a release — a gesture's dabs stream into ONE open transaction the release commits. */
export type WorldPaintOrigin = "press" | "drag" | "click";

/** 🖌️ A World3d paint gesture between events: whether its first dab streamed into the app's open tool transaction, and
 * whether the click that follows its release belongs to it. */
export type WorldPaintGesture = { readonly streamed: boolean; readonly clickConsumed: boolean };

/** 🖌️ What reaches a World3d paint gesture: a dab under the pointer, a host press, the window-level release, or a host
 * cancel (`blur`, `captureLost`). */
export type WorldPaintEvent =
  | { readonly kind: "dab"; readonly origin: WorldPaintOrigin; readonly objectId: string; readonly u: number; readonly v: number }
  | { readonly kind: "press" }
  | { readonly kind: "release" }
  | { readonly kind: "cancel"; readonly reason: "blur" | "captureLost" };

/** 🖌️ The gesture before any press. */
export const WORLD_PAINT_IDLE: WorldPaintGesture = { streamed: false, clickConsumed: false };

/** 🛠️ One step of a World3d paint gesture, pure: a press or drag dab streams into the app's ONE open tool transaction
 * (`paintAt` with `phase: "stream"`), the release commits it (`phase: "commit"`) and consumes the click that follows, a
 * cancel drops it with zero trace (`phase: "abort"` + `reason`); a click with nothing streamed is a one-shot dab (no
 * `phase`). Returns the next gesture and the one `paintAt` to dispatch, if any — the same protocol the wgpu world engine
 * publishes (a press pick, move picks, the release). */
export function worldPaintStep(gesture: WorldPaintGesture, event: WorldPaintEvent): { readonly gesture: WorldPaintGesture; readonly dispatch: Record<string, unknown> | null } {
  switch (event.kind) {
    case "press":
      return { gesture: { ...gesture, clickConsumed: false }, dispatch: null };
    case "dab":
      if (event.origin !== "click") return { gesture: { ...gesture, streamed: true }, dispatch: { objectId: event.objectId, u: event.u, v: event.v, phase: "stream" } };
      if (gesture.clickConsumed) return { gesture: { ...gesture, clickConsumed: false }, dispatch: null };
      return { gesture, dispatch: { objectId: event.objectId, u: event.u, v: event.v } };
    case "release":
      return gesture.streamed ? { gesture: { streamed: false, clickConsumed: true }, dispatch: { phase: "commit" } } : { gesture, dispatch: null };
    case "cancel":
      return gesture.streamed ? { gesture: { streamed: false, clickConsumed: false }, dispatch: { phase: "abort", reason: event.reason } } : { gesture, dispatch: null };
  }
}

/** 🕹️ What a gumball gesture grabbed — the selection mode and the opaque target ids, pinned at drag start. */
export type WorldGumballTargets = { readonly mode: string; readonly ids: readonly string[] };

/** 🛠️ A World3d gumball gesture between events: whether the selection record asked for live dispatch when it started,
 * the transform mode and handle it drags, its pinned targets, the pose its last delta reached (`sent`) and the newest
 * pose the pointer reported, whether a stream tick is in flight, whether a tick opened the app's tool transaction
 * (`streamed`), and whether a host cancel aborted it (the rest of the drag is swallowed). */
export type WorldGumballGesture = {
  readonly live: boolean;
  readonly transformMode: string | undefined;
  readonly handle: GumballHandleKind | null;
  readonly targets: WorldGumballTargets | null;
  readonly sent: GumballPose | null;
  readonly latest: GumballPose | null;
  readonly inFlight: boolean;
  readonly streamed: boolean;
  readonly aborted: boolean;
};

/** 🎛️ What reaches a World3d gumball gesture: the handle grab, a pointer pose while held, the settle of the stream tick
 * in flight, the release (with the grab pose and the live targets as fallbacks for a release without a grab), or a host
 * cancel (`blur`, `captureLost`). */
export type WorldGumballEvent =
  | { readonly kind: "start"; readonly handle: GumballHandleKind; readonly pose: GumballPose; readonly targets: WorldGumballTargets; readonly live: boolean; readonly transformMode: string | undefined }
  | { readonly kind: "drag"; readonly handle: GumballHandleKind; readonly pose: GumballPose }
  | { readonly kind: "settled" }
  | { readonly kind: "release"; readonly handle: GumballHandleKind; readonly before: GumballPose; readonly after: GumballPose; readonly targets: WorldGumballTargets }
  | { readonly kind: "cancel"; readonly reason: "blur" | "captureLost" };

/** 📨️ One gumball verb dispatch: `translateSelection` / `rotateSelection` / `scaleSelection` with its args. */
export type WorldGumballDispatch = { readonly action: string; readonly args: Record<string, unknown> };

/** 🧾️ One gumball step: the next gesture, the one dispatch it owes (if any), and why a delta it owed was skipped. */
export type WorldGumballStepResult = { readonly gesture: WorldGumballGesture; readonly dispatch: WorldGumballDispatch | null; readonly skipped?: "no-selection-ids" | "no-delta" };

/** 🫥️ The gesture before any grab. */
export const WORLD_GUMBALL_IDLE: WorldGumballGesture = { live: false, transformMode: undefined, handle: null, targets: null, sent: null, latest: null, inFlight: false, streamed: false, aborted: false };

function worldGumballDelta(transformMode: string | undefined, targets: WorldGumballTargets, handle: GumballHandleKind, before: GumballPose, after: GumballPose, phase?: "stream" | "commit"): Omit<WorldGumballStepResult, "gesture"> {
  if (targets.ids.length === 0) return { dispatch: null, skipped: "no-selection-ids" };
  const base = { mode: targets.mode, ids: [...targets.ids] };
  const payload = gumballTransformDeltaBetweenPoses(transformMode, before, after, base, handle) ?? (phase === "commit" ? gumballIdentityDelta(transformMode, base, handle) : null);
  if (!payload) return { dispatch: null, skipped: "no-delta" };
  return { dispatch: phase ? { action: payload.action, args: { ...payload.args, phase } } : payload };
}

function worldGumballPump(gesture: WorldGumballGesture): WorldGumballStepResult {
  const { sent, latest, handle, targets } = gesture;
  if (!gesture.live || gesture.aborted || gesture.inFlight || !sent || !latest || !handle || !targets || gumballPosesEqual(sent, latest)) return { gesture, dispatch: null };
  const { dispatch, skipped } = worldGumballDelta(gesture.transformMode, targets, handle, sent, latest, "stream");
  return { gesture: { ...gesture, sent: latest, inFlight: dispatch !== null, streamed: gesture.streamed || dispatch !== null }, dispatch, skipped };
}

/** 🛠️ One step of a World3d gumball gesture, pure — the host side of the gumball tool protocol
 * (`🧫️fixtures/🛠️gumball-live-protocol.json`). Local (no `gumballLiveDispatch`): the host previews the drag itself and the
 * release dispatches ONE net delta with no `phase` (a one-shot tool transaction), nothing when the pose never moved along
 * the handle. Live: every pose reported while no tick is in flight dispatches the delta from the pose the last tick
 * reached as `phase: "stream"` (one in flight, the newest pose wins), the release dispatches the remaining tail as
 * `phase: "commit"` (the identity delta of the handle's verb when the tail moved nothing), and a host cancel after a
 * streamed tick dispatches the verb's identity delta with `phase: "abort"` + `reason` and swallows the rest of the drag.
 * The targets are the ones pinned at the grab, never the selection as it stands later. */
export function worldGumballStep(gesture: WorldGumballGesture, event: WorldGumballEvent): WorldGumballStepResult {
  switch (event.kind) {
    case "start":
      return {
        gesture: { ...WORLD_GUMBALL_IDLE, live: event.live, transformMode: event.transformMode, handle: event.handle, targets: { mode: event.targets.mode, ids: [...event.targets.ids] }, sent: event.pose, latest: event.pose, inFlight: gesture.inFlight },
        dispatch: null,
      };
    case "drag":
      return worldGumballPump({ ...gesture, latest: event.pose, handle: event.handle });
    case "settled":
      return worldGumballPump({ ...gesture, inFlight: false });
    case "release": {
      const idle = { ...WORLD_GUMBALL_IDLE, inFlight: gesture.inFlight };
      if (gesture.aborted) return { gesture: idle, dispatch: null };
      const from = gesture.sent ?? event.before;
      if (!gesture.live && gumballPosesEqual(from, event.after)) return { gesture: idle, dispatch: null };
      return { gesture: idle, ...worldGumballDelta(gesture.transformMode, gesture.targets ?? event.targets, event.handle, from, event.after, gesture.live ? "commit" : undefined) };
    }
    case "cancel": {
      if (!gesture.live || !gesture.streamed || !gesture.handle || !gesture.targets) return { gesture, dispatch: null };
      const verb = gumballIdentityDelta(gesture.transformMode, { mode: gesture.targets.mode, ids: [...gesture.targets.ids] }, gesture.handle);
      return { gesture: { ...WORLD_GUMBALL_IDLE, live: true, aborted: true, inFlight: gesture.inFlight }, dispatch: { action: verb.action, args: { ...verb.args, phase: "abort", reason: event.reason } } };
    }
  }
}

/** ⚡️ Local mid-drag gumball preview delta — applied imperatively to selected instance roots so meshes track the pointer without a WASM/React round-trip (same instant path as catalogue drop ghosts). */
export type WorldGumballLivePreviewDelta =
  | { readonly kind: "translate"; readonly dx: number; readonly dy: number; readonly dz: number }
  | { readonly kind: "rotate"; readonly qx: number; readonly qy: number; readonly qz: number; readonly qw: number }
  | { readonly kind: "scale"; readonly sx: number; readonly sy: number; readonly sz: number };

/** ⚡️ Absolute start→current gumball preview delta for local instance transforms. */
export function gumballLivePreviewDeltaBetweenPoses(
  transformMode: string | undefined,
  before: GumballPose,
  after: GumballPose,
  handleKind?: GumballHandleKind,
): WorldGumballLivePreviewDelta | null {
  const kind = gumballKindForTransformMode(transformMode, handleKind);
  if (kind === "translate") {
    const dx = after.position[0] - before.position[0];
    const dy = after.position[1] - before.position[1];
    const dz = after.position[2] - before.position[2];
    if (Math.abs(dx) < GUMBALL_TRANSFORM_EPSILON && Math.abs(dy) < GUMBALL_TRANSFORM_EPSILON && Math.abs(dz) < GUMBALL_TRANSFORM_EPSILON) {
      return null;
    }
    return { kind: "translate", dx, dy, dz };
  }
  if (kind === "rotate") {
    const beforeQuat = new Quaternion(before.quaternion[0], before.quaternion[1], before.quaternion[2], before.quaternion[3]);
    const afterQuat = new Quaternion(after.quaternion[0], after.quaternion[1], after.quaternion[2], after.quaternion[3]);
    const delta = afterQuat.multiply(beforeQuat.invert());
    if (2 * Math.acos(Math.min(1, Math.max(-1, delta.w))) < GUMBALL_TRANSFORM_EPSILON) return null;
    return { kind: "rotate", qx: delta.x, qy: delta.y, qz: delta.z, qw: delta.w };
  }
  const sx = after.scale[0] / Math.max(before.scale[0], GUMBALL_TRANSFORM_EPSILON);
  const sy = after.scale[1] / Math.max(before.scale[1], GUMBALL_TRANSFORM_EPSILON);
  const sz = after.scale[2] / Math.max(before.scale[2], GUMBALL_TRANSFORM_EPSILON);
  if (Math.abs(sx - 1) < GUMBALL_TRANSFORM_EPSILON && Math.abs(sy - 1) < GUMBALL_TRANSFORM_EPSILON && Math.abs(sz - 1) < GUMBALL_TRANSFORM_EPSILON) {
    return null;
  }
  return { kind: "scale", sx, sy, sz };
}

type WorldGumballLivePose = {
  readonly position: readonly [number, number, number];
  readonly quaternion: readonly [number, number, number, number];
  readonly scale: readonly [number, number, number];
};

/** ⚡️ Applies a local gumball preview delta onto a drag-start instance pose (matches puzzle/lowpoly/CAD scratch translate/rotate/scale semantics). */
export function applyGumballLivePreviewDeltaToPose(base: WorldGumballLivePose, delta: WorldGumballLivePreviewDelta): WorldGumballLivePose {
  if (delta.kind === "translate") {
    return {
      position: [base.position[0] + delta.dx, base.position[1] + delta.dy, base.position[2] + delta.dz],
      quaternion: base.quaternion,
      scale: base.scale,
    };
  }
  if (delta.kind === "rotate") {
    const next = new Quaternion(delta.qx, delta.qy, delta.qz, delta.qw).multiply(
      new Quaternion(base.quaternion[0], base.quaternion[1], base.quaternion[2], base.quaternion[3]),
    );
    return {
      position: base.position,
      quaternion: [next.x, next.y, next.z, next.w],
      scale: base.scale,
    };
  }
  return {
    position: base.position,
    quaternion: base.quaternion,
    scale: [base.scale[0] * delta.sx, base.scale[1] * delta.sy, base.scale[2] * delta.sz],
  };
}

/**
 * 🧿️ Whether the `<group>` ref the reconciler handed back is a real three.js instance root that
 * owns a transform to write. The host mounts under hosts other than the three.js reconciler — jsdom
 * gesture mounts and `renderToStaticMarkup` — where the very same ref yields a DOM node instead, so
 * the imperative gumball preview registry admits only what it can actually pose. `isObject3D` is
 * three's own brand, which survives the realm boundary a bundled `instanceof` does not.
 *
 * @see https://threejs.org/docs/#api/en/core/Object3D.isObject3D
 */
export function isWorldInstanceRootObject3D(candidate: unknown): candidate is Group {
  return typeof candidate === "object" && candidate !== null && (candidate as { isObject3D?: unknown }).isObject3D === true;
}

/** ⚡️ Writes a live gumball preview pose onto a Three.js instance root. */
export function applyGumballLivePreviewPoseToObject3D(target: Object3D, pose: WorldGumballLivePose): void {
  target.position.set(pose.position[0], pose.position[1], pose.position[2]);
  target.quaternion.set(pose.quaternion[0], pose.quaternion[1], pose.quaternion[2], pose.quaternion[3]);
  target.scale.set(pose.scale[0], pose.scale[1], pose.scale[2]);
  target.updateMatrixWorld(true);
}

/** 🧭️ The drag-start pose of the instance a marker belongs to: the origin and orientation it turns and scales about. */
export type WorldGumballOwnerPose = {
  readonly position: readonly [number, number, number];
  readonly rotation: readonly [number, number, number, number];
};

/** 🧭️ Every instance's drag-start pose by id — what a marker of that instance is previewed about. */
export function worldGumballOwnerPoses(instances: readonly WorldInstanceRecord[]): ReadonlyMap<string, WorldGumballOwnerPose> {
  const owners = new Map<string, WorldGumballOwnerPose>();
  for (const instance of instances) owners.set(instance.id, { position: instance.position ?? [instance.x ?? 0, instance.y ?? 0, instance.z ?? 0], rotation: instance.rotation ?? [0, 0, 0, 1] });
  return owners;
}

/**
 * 🌀 One marker point (vortex, grip, attraction end) of an instance under the gumball preview, about that instance's OWN
 * origin: a turn rotates it about the owner's origin and a scale stretches it along the owner's local axes — exactly what
 * {@link applyGumballLivePreviewDeltaToPose} does to the owner itself and what the committed selection leaves do to every
 * target (puzzle `rotate-selection`/`scale-selection`, …). The gumball pivot only anchors the widget, so a multi-object
 * turn previews the markers where the release lands them instead of orbiting them about the pivot.
 */
export function gumballPreviewOwnedWorldPoint(
  owner: WorldGumballOwnerPose,
  transformMode: string | undefined,
  before: GumballPose,
  after: GumballPose,
  handleKind: GumballHandleKind | null | undefined,
  worldPoint: readonly [number, number, number],
): readonly [number, number, number] {
  const delta = gumballLivePreviewDeltaBetweenPoses(transformMode, before, after, handleKind ?? undefined);
  if (!delta) return worldPoint;
  if (delta.kind === "translate") return [worldPoint[0] + delta.dx, worldPoint[1] + delta.dy, worldPoint[2] + delta.dz];
  const offset = new Vector3(worldPoint[0] - owner.position[0], worldPoint[1] - owner.position[1], worldPoint[2] - owner.position[2]);
  if (delta.kind === "rotate") {
    offset.applyQuaternion(new Quaternion(delta.qx, delta.qy, delta.qz, delta.qw));
  } else {
    const turn = new Quaternion(owner.rotation[0], owner.rotation[1], owner.rotation[2], owner.rotation[3]);
    offset.applyQuaternion(turn.clone().invert()).multiply(new Vector3(delta.sx, delta.sy, delta.sz)).applyQuaternion(turn);
  }
  return [owner.position[0] + offset.x, owner.position[1] + offset.y, owner.position[2] + offset.z];
}

/** 🌀 One marker direction of an instance under the gumball preview: turned with the owner, or carried through the owner's local stretch and renormalized. */
export function gumballPreviewOwnedWorldDirection(
  owner: WorldGumballOwnerPose,
  transformMode: string | undefined,
  before: GumballPose,
  after: GumballPose,
  handleKind: GumballHandleKind | null | undefined,
  direction: readonly [number, number, number],
): readonly [number, number, number] {
  const delta = gumballLivePreviewDeltaBetweenPoses(transformMode, before, after, handleKind ?? undefined);
  if (!delta || delta.kind === "translate") return direction;
  const vector = new Vector3(direction[0], direction[1], direction[2]);
  if (delta.kind === "rotate") {
    vector.applyQuaternion(new Quaternion(delta.qx, delta.qy, delta.qz, delta.qw));
  } else {
    const turn = new Quaternion(owner.rotation[0], owner.rotation[1], owner.rotation[2], owner.rotation[3]);
    vector.applyQuaternion(turn.clone().invert()).multiply(new Vector3(delta.sx, delta.sy, delta.sz)).applyQuaternion(turn);
  }
  vector.normalize();
  return [vector.x, vector.y, vector.z];
}

export function gumballConfigForTransformMode(mode: string, plane?: GumballConfig["plane"]): GumballConfig {
  const groups =
    mode === "transform"
      ? { moveAxes: true, movePlanes: true, rotate: true, scaleAxes: false, scalePlanes: false, scaleUniform: false }
      : mode === "rotate"
        ? { moveAxes: false, movePlanes: false, rotate: true, scaleAxes: false, scalePlanes: false, scaleUniform: false }
        : mode === "scale"
          ? { moveAxes: false, movePlanes: false, rotate: false, scaleAxes: true, scalePlanes: true, scaleUniform: true }
          : { moveAxes: true, movePlanes: true, rotate: false, scaleAxes: false, scalePlanes: false, scaleUniform: false };
  return plane ? { ...groups, plane } : groups;
}

/** 🎛️ Transform-mode gumball config intersected with the planar subset implied by a window projection. */
export function worldGumballConfigForProjection(mode: string, projectionSpec?: WorldProjectionSpec): GumballConfig {
  return gumballConfigForTransformMode(mode, worldProjectionGumballPlane(projectionSpec));
}

/** 🫥️ True while the canvas is hovered, or always true when `enabled` is false (driver gumball reveal is `"always"`). Listens directly on the R3F canvas DOM element — no prop drilling into the scene graph. */
function useUiCanvasHovered(enabled: boolean): boolean {
  const gl = useThree((state) => state.gl);
  const [hovered, setHovered] = useState(!enabled);
  useEffect(() => {
    if (!enabled) {
      setHovered(true);
      return;
    }
    setHovered(false);
    const canvas = gl.domElement;
    const onEnter = () => setHovered(true);
    const onLeave = () => setHovered(false);
    canvas.addEventListener("pointerenter", onEnter);
    canvas.addEventListener("pointerleave", onLeave);
    return () => {
      canvas.removeEventListener("pointerenter", onEnter);
      canvas.removeEventListener("pointerleave", onLeave);
    };
  }, [enabled, gl]);
  return hovered;
}

function SceneGumball({
  target,
  config,
  active,
  onDraggingChanged,
  onDragStart,
  onDrag,
  onDragEnd,
}: {
  readonly target?: readonly [number, number, number];
  readonly config: GumballConfig;
  readonly active: boolean;
  readonly onDraggingChanged: (dragging: boolean) => void;
  readonly onDragStart?: (kind: GumballHandleKind, before: GumballPose) => void;
  readonly onDrag?: (kind: GumballHandleKind, pose: GumballPose) => void;
  readonly onDragEnd: (kind: GumballHandleKind, before: GumballPose, after: GumballPose) => void;
}) {
  const pivotRef = useRef<Object3D>(new Object3D());
  const draggingRef = useRef(false);
  const [ready, setReady] = useState(false);
  const driver = useUiDriver();
  const hovered = useUiCanvasHovered(driver.gumball === "hover");
  useEffect(() => {
    if (!target || draggingRef.current) return;
    pivotRef.current.position.set(target[0], target[1], target[2]);
    pivotRef.current.quaternion.set(0, 0, 0, 1);
    pivotRef.current.scale.set(1, 1, 1);
    pivotRef.current.updateMatrixWorld(true);
    setReady(true);
  }, [target]);
  if (!active || !target || !ready || !hovered) return null;
  return (
    <>
      <primitive object={pivotRef.current} />
      <UnifiedGumball
        target={pivotRef.current}
        config={config}
        onDraggingChanged={(dragging) => {
          draggingRef.current = dragging;
          onDraggingChanged(dragging);
        }}
        onDragStart={onDragStart}
        onDrag={onDrag}
        onDragEnd={(kind, before, after) => {
          onDragEnd(kind, before, after);
          pivotRef.current.position.set(after.position[0], after.position[1], after.position[2]);
          pivotRef.current.quaternion.set(after.quaternion[0], after.quaternion[1], after.quaternion[2], after.quaternion[3]);
          pivotRef.current.scale.set(after.scale[0], after.scale[1], after.scale[2]);
          pivotRef.current.updateMatrixWorld(true);
          draggingRef.current = false;
        }}
      />
    </>
  );
}

const WorldInstanceNode = reactHostPort.memo(function WorldInstanceNode({
  instance,
  index,
  meshRecord,
  meshData,
  geometry,
  appearance,
  borderGeometry,
  palette,
  vertexPick,
  edgeGeometry,
  paintTextureBase64,
  position,
  scale,
  quaternion,
  targets,
  activeObjectId,
  selectionMode,
  selectedComponentIds,
  previewComponentIds,
  hoveredComponent,
  showEdges,
  pickEnabled,
  onPaintAt,
  paintFromHit,
  flatShading,
  onInstancePointerDown,
  onInstancePointerMove,
  onWorldPick,
  onComponentHover,
  mergeMode,
  previewInstanceSelected,
  environmentMaterial,
  environmentShadowEnabled,
  faceDragActive,
  onFaceDragStart,
  onRootRef,
}: {
  readonly instance: WorldInstanceRecord;
  readonly index: number;
  readonly meshRecord?: WorldMeshRecord;
  readonly meshData?: WorldMeshData;
  readonly geometry?: BufferGeometry;
  readonly appearance?: WorldMeshAppearance | null;
  /** 🎨️ Shared per-meshId edge outline geometry (see {@link WorldInstancesLayer}'s `geometries` memo); never rebuilt per instance. */
  readonly borderGeometry?: EdgesGeometry;
  readonly palette: MeshStylePalette;
  readonly vertexPick: VertexPickData | null;
  readonly edgeGeometry: BufferGeometry | null;
  readonly paintTextureBase64?: string;
  readonly position: readonly [number, number, number];
  readonly scale: readonly [number, number, number];
  readonly quaternion?: Quaternion;
  readonly targets: WorldSelectionTargets;
  readonly activeObjectId?: string;
  readonly selectionMode: string;
  readonly selectedComponentIds: ReadonlySet<number>;
  readonly previewComponentIds: ReadonlySet<number>;
  readonly hoveredComponent?: WorldHoverComponent;
  readonly showEdges?: boolean;
  readonly pickEnabled: boolean;
  readonly onPaintAt?: (objectId: string, u: number, v: number, origin: WorldPaintOrigin) => void;
  readonly paintFromHit: (objectId: string, mesh: WorldMeshData, event: { faceIndex?: number | null; uv?: { x: number; y: number } }, origin: WorldPaintOrigin) => void;
  readonly flatShading?: boolean;
  readonly onInstancePointerDown: (id: string, index: number, event: { shiftKey: boolean; ctrlKey: boolean; metaKey: boolean }) => void;
  readonly onInstancePointerMove: (id: string | null) => void;
  readonly onWorldPick: (args: { granularity: string; id: number; merge: string; objectId?: string }) => void;
  readonly onComponentHover: (args: { objectId: string; mode: string; id: number } | null) => void;
  readonly mergeMode: (event: { shiftKey?: boolean; ctrlKey?: boolean; metaKey?: boolean }) => string;
  /** 🖱️➡️ When true, pointer-down on an already-selected face starts a push/pull drag instead of falling through to selection/orbit. */
  readonly faceDragActive?: boolean;
  readonly onFaceDragStart?: (args: { objectId: string; faceId: number; normal: readonly [number, number, number]; point: readonly [number, number, number]; faceExtent?: readonly [number, number] }) => void;
  /** Live marquee-drag merged selection state for this instance; undefined when no drag is in progress. */
  readonly previewInstanceSelected?: boolean;
  readonly environmentMaterial?: WorldEnvironmentMaterialRecord;
  readonly environmentShadowEnabled?: boolean;
  /** ⚡️ Registers the instance root group for imperative mid-drag gumball live preview. */
  readonly onRootRef?: (id: string, group: Group | null) => void;
}) {
  const rootRef = useCallback(
    (group: Group | null) => {
      onRootRef?.(instance.id, group);
    },
    [instance.id, onRootRef],
  );
  const chrome = useWorldInstanceChrome(instance.id, instance.objectKind);
  const isActiveObject = instance.id === activeObjectId || (instance.interactionId != null && instance.interactionId === activeObjectId);
  const colors = semanticColorsFromPalette(palette);
  const celebratingIds = useCelebratingWorldInstanceIds();
  const provisional = useToolRunProvisional(instance) || instance.provisional === true;
  const styleKind = resolveMeshSelectionPreviewStyle(
    { ...instance, provisional, selected: chrome.selected, hovered: chrome.hovered, highlighted: worldInstanceHighlighted(chrome.highlighted, instance), celebrating: celebratingIds.has(instance.id) },
    chrome.previewSelected ?? previewInstanceSelected,
  );
  const style = palette[styleKind];
  const glbUsesEnvironmentColor = styleKind === "neutral" && environmentMaterial?.color != null;
  const glbColor = glbUsesEnvironmentColor ? environmentMaterial!.color! : style.meshColor;
  const glbEmissive = glbUsesEnvironmentColor && environmentMaterial?.emissive ? environmentMaterial.emissive : style.meshColor;
  const glbEmissiveIntensity = glbUsesEnvironmentColor && environmentMaterial?.emissive ? (environmentMaterial.emissiveIntensity ?? 1) : style.emissiveIntensity;
  const instancePickEnabled = pickEnabled && !instance.disabled && !provisional;
  const lockedClickClears = instance.disabled === true;
  const hoveredFaceId = hoveredComponent?.mode === "face" && hoveredComponent.objectId === instance.id ? hoveredComponent.id : undefined;
  const hoveredVertexId = hoveredComponent?.mode === "vertex" && hoveredComponent.objectId === instance.id ? hoveredComponent.id : undefined;
  const hoveredEdgeId = hoveredComponent?.mode === "edge" && hoveredComponent.objectId === instance.id ? hoveredComponent.id : undefined;
  const selectedFaceIds = selectionMode === "face" ? selectedComponentIds : new Set<number>();
  const selectedVertexIds = selectionMode === "vertex" ? selectedComponentIds : new Set<number>();
  const selectedEdgeIds = selectionMode === "edge" ? selectedComponentIds : new Set<number>();
  const previewFaceIds = isActiveObject && selectionMode === "face" ? previewComponentIds : new Set<number>();
  const previewVertexIds = isActiveObject && selectionMode === "vertex" ? previewComponentIds : new Set<number>();
  const previewEdgeIds = isActiveObject && selectionMode === "edge" ? previewComponentIds : new Set<number>();
  const facePreviewOverlay = meshData && previewFaceIds.size > 0 ? buildFaceOverlayGeometry(meshData, previewFaceIds) : null;
  const edgePreviewOverlay = meshData && previewEdgeIds.size > 0 ? buildEdgeOverlayGeometry(meshData, previewEdgeIds) : null;
  const vertexPreviewOverlay = meshData && previewVertexIds.size > 0 ? buildVertexOverlayGeometry(meshData, previewVertexIds) : null;
  const faceSelectedOverlay = meshData ? buildFaceOverlayGeometry(meshData, selectedFaceIds) : null;
  const faceHoveredOverlay = meshData && hoveredFaceId != null ? buildFaceOverlayGeometry(meshData, new Set([hoveredFaceId])) : null;
  const edgeSelectedOverlay = meshData ? buildEdgeOverlayGeometry(meshData, selectedEdgeIds) : null;
  const edgeHoveredOverlay = meshData && hoveredEdgeId != null ? buildEdgeOverlayGeometry(meshData, new Set([hoveredEdgeId])) : null;
  const vertexSelectedOverlay = meshData ? buildVertexOverlayGeometry(meshData, selectedVertexIds) : null;
  const vertexHoveredOverlay = meshData && hoveredVertexId != null ? buildVertexOverlayGeometry(meshData, new Set([hoveredVertexId])) : null;

  const hasShadedMesh = Boolean(meshData && geometry && meshData.indices.length > 0);
  const isCurveOnly = Boolean(meshData && isCurveOnlyWorldMesh(meshData));
  const isPointOnly = Boolean(meshData && !hasShadedMesh && !edgeGeometry && vertexPick);
  const curveLineWidth = styleKind === "neutral" ? 2 : 4;

  return (
    <group ref={rootRef} position={position as [number, number, number]} scale={scale as [number, number, number]} quaternion={quaternion}>
      {meshData ? (
        <>
          {hasShadedMesh && geometry ? (
            <PaintTexturedMesh
            geometry={geometry}
            appearance={appearance}
            style={style}
            styleKind={styleKind}
            textureBase64={paintTextureBase64}
            flatShading={flatShading}
            raycast={worldInstanceMeshRaycast(instancePickEnabled)}
            onPointerDown={(event) => {
              if (onPaintAt) {
                if (event.button === 0) paintFromHit(instance.id, meshData, event, "press");
                return;
              }
              if (!faceDragActive || !onFaceDragStart || !event.face) return;
              if (!(targets.face && event.faceIndex != null && meshData.faceIds?.[event.faceIndex] != null)) return;
              const faceId = meshData.faceIds[event.faceIndex]!;
              if (!(isActiveObject && selectionMode === "face" && selectedComponentIds.has(faceId))) return;
              event.stopPropagation();
              const normal = event.face.normal.clone().transformDirection(event.object.matrixWorld).normalize();
              onFaceDragStart({
                objectId: instance.id,
                faceId,
                normal: [normal.x, normal.y, normal.z],
                point: [event.point.x, event.point.y, event.point.z],
                faceExtent: faceExtentFromMesh(meshData, faceId),
              });
            }}
            onClick={(event) => {
              if (onPaintAt) {
                paintFromHit(instance.id, meshData, event, "click");
                return;
              }
              if (lockedClickClears) {
                event.stopPropagation();
                onInstancePointerDown(instance.id, index, event);
                return;
              }
              if (!instancePickEnabled) return;
              event.stopPropagation();
              if (targets.face && event.faceIndex != null && meshData.faceIds?.[event.faceIndex] != null) {
                onWorldPick({
                  granularity: "face",
                  id: meshData.faceIds[event.faceIndex]!,
                  merge: mergeMode(event),
                  objectId: instance.id,
                });
              } else if (targets.mesh) {
                onInstancePointerDown(instance.id, index, event);
              }
            }}
            onPointerMove={(event) => {
              if (onPaintAt) {
                if ((event.buttons & 1) !== 0) paintFromHit(instance.id, meshData, event, "drag");
                return;
              }
              if (!instancePickEnabled) return;
              event.stopPropagation();
              if (targets.face && event.faceIndex != null && meshData.faceIds?.[event.faceIndex] != null) {
                onComponentHover({
                  objectId: instance.id,
                  mode: "face",
                  id: meshData.faceIds[event.faceIndex]!,
                });
              } else {
                onInstancePointerMove(instance.id);
              }
            }}
            onPointerOut={() => {
              onInstancePointerMove(null);
              onComponentHover(null);
            }}
          ></PaintTexturedMesh>
          ) : null}
          {hasShadedMesh && borderGeometry && (showEdges ?? true) && !edgeGeometry && !provisional ? (
            <lineSegments geometry={borderGeometry} scale={1.001} raycast={() => null} renderOrder={2}>
              <lineBasicMaterial color={style.lineColor} depthTest={false} />
            </lineSegments>
          ) : null}
          {provisional && borderGeometry ? <ToolRunProvisionalOutline geometry={borderGeometry} /> : null}
          {(targets.edge || isCurveOnly || (showEdges ?? true) || (selectionMode === "mesh" && selectedComponentIds.size > 0)) && edgeGeometry ? (
            <lineSegments
              geometry={edgeGeometry}
              renderOrder={2}
              onClick={(event) => {
                if (lockedClickClears) {
                  event.stopPropagation();
                  onInstancePointerDown(instance.id, index, event);
                  return;
                }
                if (!instancePickEnabled) return;
                // 🧵️ Displayed edges (`showEdges`) are not pick targets unless edge granularity is armed: let the
                // hit fall through to the face/instance under it instead of swallowing every click near a seam.
                if (!targets.edge && !isCurveOnly) return;
                event.stopPropagation();
                // 🧵️ Centerline/curve objects are the model-definition instances — never decompose into edge components.
                if (isCurveOnly && targets.mesh) {
                  onInstancePointerDown(instance.id, index, event);
                  return;
                }
                if (meshData.edgeIds?.length) {
                  const edgeIndex = Math.floor((event.index ?? 0) / 2);
                  const edgeId = meshData.edgeIds[edgeIndex];
                  if (edgeId != null) {
                    onWorldPick({ granularity: "edge", id: edgeId, merge: mergeMode(event), objectId: instance.id });
                    return;
                  }
                }
                if (targets.mesh) {
                  onInstancePointerDown(instance.id, index, event);
                }
              }}
              onPointerMove={(event) => {
                if (!instancePickEnabled) return;
                if (!targets.edge && !isCurveOnly) return;
                event.stopPropagation();
                if (isCurveOnly) {
                  onInstancePointerMove(instance.id);
                  return;
                }
                if (!meshData?.edgeIds?.length) return;
                const edgeIndex = Math.floor((event.index ?? 0) / 2);
                const edgeId = meshData.edgeIds[edgeIndex];
                if (edgeId == null) return;
                onComponentHover({ objectId: instance.id, mode: "edge", id: edgeId });
              }}
              onPointerOut={() => {
                if (isCurveOnly) onInstancePointerMove(null);
                onComponentHover(null);
              }}
            >
              <lineBasicMaterial color={style.lineColor} linewidth={isCurveOnly ? curveLineWidth : 1} depthTest={false} />
            </lineSegments>
          ) : null}
          {(targets.vertex || isPointOnly) && vertexPick ? (
            <points
              geometry={vertexPick.geometry}
              onClick={(event) => {
                if (lockedClickClears) {
                  event.stopPropagation();
                  onInstancePointerDown(instance.id, index, event);
                  return;
                }
                if (!instancePickEnabled) return;
                event.stopPropagation();
                if (!targets.vertex) {
                  if (targets.mesh) onInstancePointerDown(instance.id, index, event);
                  return;
                }
                const idx = event.index ?? 0;
                const vertexId = vertexPick.vertexIds[idx];
                if (vertexId == null) return;
                onWorldPick({ granularity: "vertex", id: vertexId, merge: mergeMode(event), objectId: instance.id });
              }}
              onPointerMove={(event) => {
                if (!instancePickEnabled) return;
                event.stopPropagation();
                if (!targets.vertex) {
                  onInstancePointerMove(instance.id);
                  return;
                }
                const idx = event.index ?? 0;
                const vertexId = vertexPick.vertexIds[idx];
                if (vertexId == null) return;
                onComponentHover({ objectId: instance.id, mode: "vertex", id: vertexId });
              }}
              onPointerOut={() => { onInstancePointerMove(null); onComponentHover(null); }}
            >
              {/* 📍️ Screen-space dots: a world-unit size (0.05) is sub-pixel on a six-unit mesh seen from
                  thirty units away, so vertex mode showed nothing to hover or pick (lowpoly, 2026-09-18). */}
              <pointsMaterial color={isPointOnly ? style.lineColor : colors.edge} size={WORLD_VERTEX_DOT_PX} sizeAttenuation={false} />
            </points>
          ) : null}
          {faceSelectedOverlay ? (
            <mesh geometry={faceSelectedOverlay} raycast={() => null}>
              <meshBasicMaterial color={colors.select} transparent opacity={0.62} side={DoubleSide} depthWrite={false} polygonOffset polygonOffsetFactor={-2} />
            </mesh>
          ) : null}
          {faceHoveredOverlay ? (
            <mesh geometry={faceHoveredOverlay} raycast={() => null}>
              <meshBasicMaterial color={colors.hover} transparent opacity={0.48} side={DoubleSide} depthWrite={false} polygonOffset polygonOffsetFactor={-3} />
            </mesh>
          ) : null}
          {facePreviewOverlay ? (
            <mesh geometry={facePreviewOverlay} raycast={() => null}>
              <meshBasicMaterial color={colors.hover} transparent opacity={0.36} side={DoubleSide} depthWrite={false} polygonOffset polygonOffsetFactor={-4} />
            </mesh>
          ) : null}
          {edgeSelectedOverlay ? (
            <lineSegments geometry={edgeSelectedOverlay} raycast={() => null} renderOrder={3}>
              <lineBasicMaterial color={colors.select} linewidth={3} depthTest={false} />
            </lineSegments>
          ) : null}
          {edgeHoveredOverlay ? (
            <lineSegments geometry={edgeHoveredOverlay} raycast={() => null} renderOrder={4}>
              <lineBasicMaterial color={colors.edgeHover} linewidth={3} depthTest={false} />
            </lineSegments>
          ) : null}
          {edgePreviewOverlay ? (
            <lineSegments geometry={edgePreviewOverlay} raycast={() => null} renderOrder={3}>
              <lineBasicMaterial color={colors.edgeHover} linewidth={2} depthTest={false} />
            </lineSegments>
          ) : null}
          {vertexSelectedOverlay ? (
            <points geometry={vertexSelectedOverlay} raycast={() => null}>
              <pointsMaterial color={colors.select} size={WORLD_VERTEX_MARK_PX} sizeAttenuation={false} depthTest={false} />
            </points>
          ) : null}
          {vertexHoveredOverlay ? (
            <points geometry={vertexHoveredOverlay} raycast={() => null}>
              <pointsMaterial color={colors.hover} size={WORLD_VERTEX_MARK_PX} sizeAttenuation={false} depthTest={false} />
            </points>
          ) : null}
          {vertexPreviewOverlay ? (
            <points geometry={vertexPreviewOverlay} raycast={() => null}>
              <pointsMaterial color={colors.hover} size={WORLD_VERTEX_MARK_PX} sizeAttenuation={false} depthTest={false} />
            </points>
          ) : null}
        </>
      ) : meshRecord?.url ? (
        <group
          onPointerDown={(event) => {
            if (!instancePickEnabled && !lockedClickClears) return;
            event.stopPropagation();
            onInstancePointerDown(instance.id, index, event);
          }}
          onPointerMove={(event) => {
            if (!instancePickEnabled) return;
            event.stopPropagation();
            onInstancePointerMove(instance.id);
          }}
          onPointerOut={() => onInstancePointerMove(null)}
        >
          <Suspense fallback={null}>
            <GlbInstanceMesh
              key={worldMeshMaterialRevision(styleKind)}
              url={meshRecord.url}
              color={glbColor}
              emissive={glbEmissive}
              emissiveIntensity={glbEmissiveIntensity}
              opacity={style.opacity}
              borderColor={environmentMaterial?.stroke ?? palette.neutral.lineColor}
              material={environmentMaterial}
              shadowEnabled={environmentShadowEnabled}
              revision={styleKind}
              pickEnabled={instancePickEnabled}
            />
          </Suspense>
        </group>
      ) : (
        <mesh
          raycast={worldInstanceMeshRaycast(instancePickEnabled)}
          onPointerDown={(event) => {
            if (!instancePickEnabled && !lockedClickClears) return;
            event.stopPropagation();
            onInstancePointerDown(instance.id, index, event);
          }}
        >
          <boxGeometry args={[1, 1, 1]} />
          <meshStandardMaterial key={worldMeshMaterialRevision(styleKind)} color={style.meshColor} metalness={0} roughness={1} emissive={style.meshColor} emissiveIntensity={style.emissiveIntensity} transparent={style.opacity < 1} opacity={style.opacity} />
        </mesh>
      )}
    </group>
  );
});
//#endregion WorldSceneParsing

//#region WorldInstancesLayer
const WORLD_INSTANCE_UNIT_SCALE: readonly [number, number, number] = [1, 1, 1];
const WORLD_INSTANCE_QUATERNION = new WeakMap<WorldInstanceRecord, Quaternion>();

/** 🪪️ One `Quaternion` per instance record object, so an unchanged record (kept by `advanceWorldInstanceResidency`) hands its
 * memoized `WorldInstanceNode` the same prop instead of a fresh object per render. */
function worldInstanceQuaternion(instance: WorldInstanceRecord): Quaternion | undefined {
  const rotation = instance.rotation;
  if (!rotation) return undefined;
  let quaternion = WORLD_INSTANCE_QUATERNION.get(instance);
  if (!quaternion) {
    quaternion = new Quaternion(rotation[0], rotation[1], rotation[2], rotation[3]);
    WORLD_INSTANCE_QUATERNION.set(instance, quaternion);
  }
  return quaternion;
}

/** 🧊️ Retains the viewport's existing visual leases for both drawing and accessible publication status. */
function useWorldMeshVisuals(meshes:readonly WorldMeshRecord[]):Map<string,MeshVisuals>{
  const meshVisualsRef = useRef(new Map<string, MeshVisuals>());
  const retiredMeshVisualsRef = useRef<MeshVisuals[]>([]);
  const meshVisuals = useMemo(() => {
    const held = meshVisualsRef.current;
    const next = new Map<string, MeshVisuals>();
    const closeSpan = hopTrace.open("mesh.decode", { meshes: meshes.length });
    let built = 0;
    for (const mesh of meshes) {
      const existing = held.get(mesh.id);
      if (existing && existing.record === mesh) {
        next.set(mesh.id, existing);
        continue;
      }
      if (existing) retiredMeshVisualsRef.current.push(existing);
      try{next.set(mesh.id, buildMeshVisuals(mesh));}catch(error){next.set(mesh.id,{record:mesh,geometry:null,border:null,vertexPick:null,edge:null,appearance:null,fault:error instanceof Error?error.message:String(error),closed:false});}
      built += 1;
    }
    for (const [meshId, existing] of held) if (!next.has(meshId)) retiredMeshVisualsRef.current.push(existing);
    meshVisualsRef.current = next;
    closeSpan({ built, kept: meshes.length - built });
    return next;
  }, [meshes]);
  // 🧹️ Dispose-on-remove, after the commit that stopped referencing them: a geometry retired during
  // render is still in the mounted scene until React commits the new one.
  useEffect(() => {
    const retired = retiredMeshVisualsRef.current;
    retiredMeshVisualsRef.current = [];
    for (const entry of retired) disposeMeshVisuals(entry);
  }, [meshVisuals]);
  useEffect(
    () => () => {
      for (const entry of meshVisualsRef.current.values()) disposeMeshVisuals(entry);
      meshVisualsRef.current = new Map();
      for (const entry of retiredMeshVisualsRef.current) disposeMeshVisuals(entry);
      retiredMeshVisualsRef.current = [];
    },
    [],
  );
  return meshVisuals;
}

function WorldInstancesLayer({
  meshVisuals,
  instances,
  meshes,
  selection,
  persistentSelectionMode,
  palette,
  projectionSpec,
  onInstancePointerDown,
  onInstancePointerMove,
  onLocalHoverRelease,
  onHoverPaint,
  onWorldPick,
  onComponentHover,
  onPaintAt,
  gumballDragActive,
  controllerId,
  gumballPreviewSourceId,
  sharedGumballPreview,
  onGumballDraggingChanged,
  gumballLiveDispatch,
  onGumballDragStart,
  onGumballDrag,
  onGumballDragEnd,
  onFaceDragStart,
  mergedComponentIds,
  mergedInstanceIds,
  blockPick,
  environment,
}: {
  readonly meshVisuals:ReadonlyMap<string,MeshVisuals>;
  readonly instances: readonly WorldInstanceRecord[];
  readonly meshes: readonly WorldMeshRecord[];
  readonly selection: WorldSelectionRecord;
  /** 🐚️ This shell's own `SelectionModeStore` value — see `resolveWorldMergeMode`'s doc. */
  readonly persistentSelectionMode: MergeMode;
  readonly palette: MeshStylePalette;
  readonly projectionSpec?: WorldProjectionSpec;
  readonly onInstancePointerDown: (id: string, index: number, event: { shiftKey: boolean; ctrlKey: boolean; metaKey: boolean }) => void;
  readonly onInstancePointerMove: (id: string | null) => void;
  /** 🎯️ Subscribes a "the pointer left this pane" listener; returns the unsubscribe. The host fires it
   * from the canvas root's `pointerleave` so the layer withdraws its local hover claim. */
  readonly onLocalHoverRelease?: (listener: () => void) => () => void;
  /** 🩺️ What the hover chrome currently paints (raycast claim merged with the guest echo) — the host
   * mirrors it onto `data-hover-paint-id` so a probe reads the painted hover, not only the echoed one. */
  readonly onHoverPaint?: (id: string | null) => void;
  readonly onWorldPick: (args: { granularity: string; id: number; merge: string; objectId?: string }) => void;
  readonly onComponentHover: (args: { objectId: string; mode: string; id: number } | null) => void;
  readonly onPaintAt?: (objectId: string, u: number, v: number, origin: WorldPaintOrigin) => void;
  readonly gumballDragActive: boolean;
  readonly controllerId: string;
  readonly gumballPreviewSourceId: string;
  readonly sharedGumballPreview: WorldGumballTransformPreview | null;
  readonly onGumballDraggingChanged: (dragging: boolean) => void;
  /** ⚡️ The document owns the mid-drag pose (see `WorldSelectionRecord.gumballLiveDispatch`): no local
   * instance preview is written or shared, the instances draw whatever `instancesJson` says. */
  readonly gumballLiveDispatch: boolean;
  readonly onGumballDragStart?: (kind: GumballHandleKind, before: GumballPose) => void;
  readonly onGumballDrag?: (kind: GumballHandleKind, pose: GumballPose) => void;
  readonly onGumballDragEnd: (kind: GumballHandleKind, before: GumballPose, after: GumballPose) => void;
  readonly onFaceDragStart?: (args: { objectId: string; faceId: number; normal: readonly [number, number, number]; point: readonly [number, number, number]; faceExtent?: readonly [number, number] }) => void;
  /** Live drag-preview merged component id set (null when no marquee drag is in progress). */
  readonly mergedComponentIds?: readonly number[] | null;
  /** Live drag-preview merged whole-instance id set (null when no marquee drag is in progress). */
  readonly mergedInstanceIds?: readonly string[] | null;
  /** Disables instance picking; passed for brush engagements so a click meant for a vortex marker can't fall through and select/gumball the underlying object instead. */
  readonly blockPick?: boolean;
  readonly environment?: WorldEnvironmentRecord | null;
}) {
  const meshById = useMemo(() => new Map(meshes.map((mesh) => [mesh.id, mesh])), [meshes]);
  // 🖱️ The component (vertex/edge/face) under the pointer, painted from THIS pane's own raycast the
  // moment the pointer reaches it. The guest echoes the same hover back in its selection JSON
  // (`hoveredComponent`) a few turns later; until then — and for a guest that never echoes it — the
  // local hit is what highlights. Cleared on pointer-out and on every object-level hover, so a stale
  // face highlight never outlives the pointer leaving the mesh (lowpoly, 2026-09-18).
  const [localHoveredComponent, setLocalHoveredComponent] = useState<WorldHoverComponent | null>(null);
  const onComponentHoverPainted = useCallback(
    (args: { objectId: string; mode: string; id: number } | null) => {
      setLocalHoveredComponent((prior) => {
        const next = args && args.mode !== "mesh" && args.mode !== "object" ? args : null;
        if (prior === next || (prior && next && prior.objectId === next.objectId && prior.mode === next.mode && prior.id === next.id)) return prior;
        return next;
      });
      onComponentHover(args);
    },
    [onComponentHover],
  );
  const hoveredComponent = localHoveredComponent ?? selection.hoveredComponent;
  // 🧊️ Per-mesh-id visuals, keyed on the mesh RECORD's identity (`advanceWorldMeshResidency` keeps
  // that identity across a refresh that did not touch the mesh), so an N-mesh surface with one moved
  // mesh allocates one `BufferGeometry` instead of N — and every retired one is disposed.
  const geometries = useMemo(() => {
    const map = new Map<string, BufferGeometry>();
    for (const [meshId, entry] of meshVisuals) if (entry.geometry) map.set(meshId, entry.geometry);
    return map;
  }, [meshVisuals]);
  /** 🎨️ Per-meshId border outline geometry, shared by every instance of that mesh — never rebuilt per instance. */
  const borderGeometries = useMemo(() => {
    const map = new Map<string, EdgesGeometry>();
    for (const [meshId, entry] of meshVisuals) if (entry.border) map.set(meshId, entry.border);
    return map;
  }, [meshVisuals]);
  const vertexPickByMeshId = useMemo(() => {
    const map = new Map<string, VertexPickData | null>();
    for (const [meshId, entry] of meshVisuals) if (entry.record.data) map.set(meshId, entry.vertexPick);
    return map;
  }, [meshVisuals]);
  const edgeGeometryByMeshId = useMemo(() => {
    const map = new Map<string, BufferGeometry | null>();
    for (const [meshId, entry] of meshVisuals) if (entry.record.data) map.set(meshId, entry.edge);
    return map;
  }, [meshVisuals]);
  const targets = useMemo(() => selection.targets ?? { mesh: true, vertex: false, edge: false, face: false }, [selection.targets]);
  const selectionMode = selection.selectionMode ?? selection.granularity ?? "mesh";
  const currentComponentIds = new Set(selection.componentIds ?? []);
  const mergedComponentIdsSet = mergedComponentIds ? new Set(mergedComponentIds) : null;
  // Still-selected (solid) = current ∩ merged when dragging; newly-added (preview tint) = merged − current.
  const selectedComponentIds = useMemo(
    () => (mergedComponentIdsSet ? new Set([...currentComponentIds].filter((id) => mergedComponentIdsSet.has(id))) : currentComponentIds),
    [currentComponentIds, mergedComponentIdsSet],
  );
  const previewComponentIds = useMemo(
    () => (mergedComponentIdsSet ? new Set([...mergedComponentIdsSet].filter((id) => !currentComponentIds.has(id))) : new Set<number>()),
    [currentComponentIds, mergedComponentIdsSet],
  );
  const analyticComponentIdsByInstance = useMemo(() => {
    const byInstance = new Map<string, Set<number>>();
    const byTarget = new Map(instances.map(instance => [instance.interactionId ?? instance.id, instance]));
    for (const target of selection.gumballSelectionIds ?? []) {
      const address = /^(.+)\.(vertex|edge|face)\.(0|[1-9][0-9]*)~/.exec(target);
      if (!address || address[2] !== selectionMode) continue;
      const instance = byTarget.get(address[1]!);
      const group = Number(address[3]);
      if (!instance?.componentSource || !Number.isSafeInteger(group)) continue;
      const mesh = meshById.get(instance.meshId ?? instance.id);
      if (!mesh || world3dComponentInteractionTarget([instance], [mesh], instance.id, address[2]!, group)?.id !== target) continue;
      let groups = byInstance.get(instance.id);
      if (!groups) byInstance.set(instance.id, groups = new Set());
      groups.add(group);
    }
    return byInstance;
  }, [instances, meshById, selection.gumballSelectionIds, selectionMode]);
  const mergedInstanceIdsSet = mergedInstanceIds ? new Set(mergedInstanceIds) : null;
  const selectedIds = selection.ids ?? [];
  const instanceChromeStore = useMemo(() => createWorldInstanceChromeStore(), []);
  reactHostPort.useLayoutEffect(() => {
    instanceChromeStore.setSnapshot({
      selectedIds: new Set(selection.ids ?? []),
      hoveredId: selection.hoveredId ?? null,
      hoveredKindId: selection.hoveredKindId ?? null,
      previewInstanceIds: mergedInstanceIdsSet,
    });
  }, [instanceChromeStore, mergedInstanceIdsSet, selection.hoveredId, selection.hoveredKindId, selection.ids]);
  // 🎯️ The raycast result paints BEFORE it is dispatched: the hover chrome follows the pointer at
  // raycast speed and the guest's echo (`selection.hoveredId`, one round trip later) only confirms it
  // — see `worldHoverPaintIdV1`. The claim is withdrawn when the pointer leaves the canvas
  // (`onLocalHoverRelease`), so a hover another surface authors shows once the pointer is elsewhere.
  const handleLocalInstancePointerMove = useCallback(
    (id: string | null) => {
      instanceChromeStore.setLocalHover(id);
      onInstancePointerMove(id);
    },
    [instanceChromeStore, onInstancePointerMove],
  );
  reactHostPort.useEffect(() => {
    if (!onLocalHoverRelease) return undefined;
    return onLocalHoverRelease(() => instanceChromeStore.setLocalHover(undefined));
  }, [instanceChromeStore, onLocalHoverRelease]);
  reactHostPort.useEffect(() => {
    if (!onHoverPaint) return undefined;
    const publish = () => onHoverPaint(worldHoverPaintIdV1(instanceChromeStore.localHover(), instanceChromeStore.getSnapshot().hoveredId));
    publish();
    return instanceChromeStore.subscribe(publish);
  }, [instanceChromeStore, onHoverPaint]);
  const pickEnabled = !gumballDragActive && !onPaintAt && !blockPick && !mergedComponentIdsSet && !mergedInstanceIdsSet;
  const transformMode = selection.transformMode;
  const transformGumballMode = isWorldTransformGumballMode(transformMode);
  const gumballConfig = useMemo(() => {
    if (selection.gumballConfig) {
      const plane = worldProjectionGumballPlane(projectionSpec);
      return plane ? { ...selection.gumballConfig, plane } : selection.gumballConfig;
    }
    return worldGumballConfigForProjection(transformMode ?? "move", projectionSpec);
  }, [selection.gumballConfig, transformMode, projectionSpec]);
  const paintMode = selection.interactionMode === "paint";
  const gumballVisible = Boolean(selection.gumballActive) && transformGumballMode && !paintMode;
  const invalidate = useThree((state) => state.invalidate);
  const instanceRootsRef = useRef(new Map<string, Group>());
  const gumballLiveBasesRef = useRef(new Map<string, WorldGumballLivePose>());
  /** ⚡️ Final local poses held across the post-drag React frame(s) until `instancesJson` catches up — prevents a one-frame snap-back to the pre-drag pose. */
  const gumballCommitHoldRef = useRef(new Map<string, WorldGumballLivePose>());
  const gumballLiveStartPoseRef = useRef<GumballPose | null>(null);
  const gumballLivePoseRef = useRef<GumballPose | null>(null);
  const gumballLiveKindRef = useRef<GumballHandleKind | null>(null);
  const gumballPreviewPivotRef = useRef<readonly [number, number, number]>([0, 0, 0]);

  const publishGumballPreview = useCallback(
    (before: GumballPose, after: GumballPose, handleKind: GumballHandleKind | null, instanceIds: readonly string[]) => {
      if (!controllerId || instanceIds.length === 0) return;
      setWorldGumballTransformPreview(controllerId, {
        sourceId: gumballPreviewSourceId,
        transformMode,
        handleKind,
        before,
        after,
        instanceIds,
        pivot: gumballPreviewPivotRef.current,
      });
    },
    [controllerId, gumballPreviewSourceId, transformMode],
  );

  const registerInstanceRoot = useCallback((id: string, group: Group | null) => {
    if (isWorldInstanceRootObject3D(group)) instanceRootsRef.current.set(id, group);
    else instanceRootsRef.current.delete(id);
  }, []);

  const writeGumballPreviewPoses = useCallback(
    (poses: ReadonlyMap<string, WorldGumballLivePose>) => {
      for (const [id, pose] of poses) {
        const root = instanceRootsRef.current.get(id);
        if (!root) continue;
        applyGumballLivePreviewPoseToObject3D(root, pose);
      }
      invalidate();
    },
    [invalidate],
  );

  const applyGumballLivePreview = useCallback(
    (before: GumballPose, after: GumballPose, handleKind: GumballHandleKind | null) => {
      const delta = gumballLivePreviewDeltaBetweenPoses(transformMode, before, after, handleKind ?? undefined);
      const poses = new Map<string, WorldGumballLivePose>();
      for (const [id, base] of gumballLiveBasesRef.current) {
        poses.set(id, delta ? applyGumballLivePreviewDeltaToPose(base, delta) : base);
      }
      writeGumballPreviewPoses(poses);
      publishGumballPreview(before, after, handleKind, [...gumballLiveBasesRef.current.keys()]);
      return poses;
    },
    [publishGumballPreview, transformMode, writeGumballPreviewPoses],
  );

  const applySharedGumballPreview = useCallback(
    (preview: WorldGumballTransformPreview) => {
      const delta = gumballLivePreviewDeltaBetweenPoses(preview.transformMode, preview.before, preview.after, preview.handleKind ?? undefined);
      const poses = new Map<string, WorldGumballLivePose>();
      for (const id of preview.instanceIds) {
        const instance = instances.find((entry) => entry.id === id);
        if (!instance) continue;
        const position = instance.position ?? [instance.x ?? 0, instance.y ?? 0, instance.z ?? 0];
        const scale = instance.scale ?? [1, 1, 1];
        const rotation = instance.rotation ?? [0, 0, 0, 1];
        const base: WorldGumballLivePose = {
          position: [position[0], position[1], position[2]],
          quaternion: [rotation[0], rotation[1], rotation[2], rotation[3]],
          scale: [scale[0], scale[1], scale[2]],
        };
        poses.set(id, delta ? applyGumballLivePreviewDeltaToPose(base, delta) : base);
      }
      writeGumballPreviewPoses(poses);
    },
    [instances, writeGumballPreviewPoses],
  );

  const resetGumballPreviewPosesFromInstances = useCallback(() => {
    for (const instance of instances) {
      const root = instanceRootsRef.current.get(instance.id);
      if (!root) continue;
      const position = instance.position ?? [instance.x ?? 0, instance.y ?? 0, instance.z ?? 0];
      const scale = instance.scale ?? [1, 1, 1];
      const rotation = instance.rotation ?? [0, 0, 0, 1];
      applyGumballLivePreviewPoseToObject3D(root, {
        position: [position[0], position[1], position[2]],
        quaternion: [rotation[0], rotation[1], rotation[2], rotation[3]],
        scale: [scale[0], scale[1], scale[2]],
      });
    }
    invalidate();
  }, [instances, invalidate]);

  useLayoutEffect(() => {
    const before = gumballLiveStartPoseRef.current;
    const after = gumballLivePoseRef.current;
    if (gumballDragActive && before && after) {
      applyGumballLivePreview(before, after, gumballLiveKindRef.current);
      return;
    }
    if (!gumballDragActive && sharedGumballPreview && sharedGumballPreview.sourceId !== gumballPreviewSourceId) {
      applySharedGumballPreview(sharedGumballPreview);
      return;
    }
    if (!gumballDragActive && !sharedGumballPreview && gumballCommitHoldRef.current.size === 0) {
      resetGumballPreviewPosesFromInstances();
      return;
    }
    const hold = gumballCommitHoldRef.current;
    if (hold.size === 0) return;
    writeGumballPreviewPoses(hold);
    let allMatch = true;
    for (const [id, pose] of hold) {
      const instance = instances.find((entry) => entry.id === id);
      if (!instance) {
        allMatch = false;
        continue;
      }
      const position = instance.position ?? [instance.x ?? 0, instance.y ?? 0, instance.z ?? 0];
      const scale = instance.scale ?? [1, 1, 1];
      const rotation = instance.rotation ?? [0, 0, 0, 1];
      if (
        Math.abs(position[0] - pose.position[0]) > GUMBALL_TRANSFORM_EPSILON ||
        Math.abs(position[1] - pose.position[1]) > GUMBALL_TRANSFORM_EPSILON ||
        Math.abs(position[2] - pose.position[2]) > GUMBALL_TRANSFORM_EPSILON ||
        Math.abs(scale[0] - pose.scale[0]) > GUMBALL_TRANSFORM_EPSILON ||
        Math.abs(scale[1] - pose.scale[1]) > GUMBALL_TRANSFORM_EPSILON ||
        Math.abs(scale[2] - pose.scale[2]) > GUMBALL_TRANSFORM_EPSILON ||
        Math.abs(rotation[0] - pose.quaternion[0]) > GUMBALL_TRANSFORM_EPSILON ||
        Math.abs(rotation[1] - pose.quaternion[1]) > GUMBALL_TRANSFORM_EPSILON ||
        Math.abs(rotation[2] - pose.quaternion[2]) > GUMBALL_TRANSFORM_EPSILON ||
        Math.abs(rotation[3] - pose.quaternion[3]) > GUMBALL_TRANSFORM_EPSILON
      ) {
        allMatch = false;
      }
    }
    if (allMatch) hold.clear();
  }, [applyGumballLivePreview, applySharedGumballPreview, gumballDragActive, gumballPreviewSourceId, instances, resetGumballPreviewPosesFromInstances, sharedGumballPreview, writeGumballPreviewPoses]);

  useEffect(
    () => () => {
      clearWorldGumballTransformPreview(controllerId, gumballPreviewSourceId);
    },
    [controllerId, gumballPreviewSourceId],
  );

  const handleGumballDraggingChanged = useCallback(
    (dragging: boolean) => {
      if (dragging) gumballCommitHoldRef.current.clear();
      onGumballDraggingChanged(dragging);
    },
    [onGumballDraggingChanged],
  );

  const handleGumballDragStart = useCallback(
    (kind: GumballHandleKind, before: GumballPose) => {
      if (gumballLiveDispatch) {
        gumballLiveBasesRef.current.clear();
        gumballCommitHoldRef.current.clear();
        onGumballDragStart?.(kind, before);
        return;
      }
      gumballPreviewPivotRef.current = selection.gumballTarget ?? [before.position[0], before.position[1], before.position[2]];
      const bases = new Map<string, WorldGumballLivePose>();
      for (const id of selectedIds) {
        const root = instanceRootsRef.current.get(id);
        if (!root) continue;
        bases.set(id, {
          position: [root.position.x, root.position.y, root.position.z],
          quaternion: [root.quaternion.x, root.quaternion.y, root.quaternion.z, root.quaternion.w],
          scale: [root.scale.x, root.scale.y, root.scale.z],
        });
      }
      gumballLiveBasesRef.current = bases;
      gumballCommitHoldRef.current.clear();
      gumballLiveStartPoseRef.current = before;
      gumballLivePoseRef.current = before;
      gumballLiveKindRef.current = kind;
      publishGumballPreview(before, before, kind, selectedIds);
      onGumballDragStart?.(kind, before);
    },
    [gumballLiveDispatch, onGumballDragStart, publishGumballPreview, selectedIds, selection.gumballTarget],
  );

  const handleGumballDrag = useCallback(
    (kind: GumballHandleKind, pose: GumballPose) => {
      if (gumballLiveDispatch) {
        onGumballDrag?.(kind, pose);
        return;
      }
      const before = gumballLiveStartPoseRef.current ?? pose;
      gumballLiveStartPoseRef.current = before;
      gumballLivePoseRef.current = pose;
      gumballLiveKindRef.current = kind;
      applyGumballLivePreview(before, pose, kind);
      onGumballDrag?.(kind, pose);
    },
    [applyGumballLivePreview, gumballLiveDispatch, onGumballDrag],
  );

  const handleGumballDragEnd = useCallback(
    (kind: GumballHandleKind, before: GumballPose, after: GumballPose) => {
      if (gumballLiveDispatch) {
        onGumballDragEnd(kind, before, after);
        return;
      }
      const start = gumballLiveStartPoseRef.current ?? before;
      const finals = applyGumballLivePreview(start, after, kind);
      gumballCommitHoldRef.current = finals;
      gumballLiveBasesRef.current.clear();
      gumballLiveStartPoseRef.current = null;
      gumballLivePoseRef.current = null;
      gumballLiveKindRef.current = null;
      clearWorldGumballTransformPreview(controllerId, gumballPreviewSourceId);
      onGumballDragEnd(kind, before, after);
    },
    [applyGumballLivePreview, controllerId, gumballLiveDispatch, gumballPreviewSourceId, onGumballDragEnd],
  );

  // 🪪️ Stable across renders, like every other `WorldInstanceNode` prop: an inline function here defeated the node's memo, so
  // every refresh re-rendered every instance of the document even when one instance changed.
  const mergeMode = useCallback(
    (event: { shiftKey?: boolean; ctrlKey?: boolean; metaKey?: boolean }) => componentPickMergeMode(resolveWorldMergeMode(selection.selectionMergeMode, event, persistentSelectionMode)),
    [selection.selectionMergeMode, persistentSelectionMode],
  );

  const paintFromHit = useCallback((objectId: string, mesh: WorldMeshData, event: { faceIndex?: number | null; uv?: { x: number; y: number } }, origin: WorldPaintOrigin) => {
    if (!onPaintAt) return;
    let u = event.uv?.x;
    let v = event.uv?.y;
    if (u == null || v == null) {
      if (event.faceIndex == null || !mesh.indices.length) return;
      const i0 = mesh.indices[event.faceIndex * 3] ?? 0;
      const i1 = mesh.indices[event.faceIndex * 3 + 1] ?? 0;
      const i2 = mesh.indices[event.faceIndex * 3 + 2] ?? 0;
      if (!mesh.uvs || mesh.uvs.length < 6) return;
      u = (mesh.uvs[i0 * 2]! + mesh.uvs[i1 * 2]! + mesh.uvs[i2 * 2]!) / 3;
      v = (mesh.uvs[i0 * 2 + 1]! + mesh.uvs[i1 * 2 + 1]! + mesh.uvs[i2 * 2 + 1]!) / 3;
    }
    onPaintAt(objectId, u, v, origin);
  }, [onPaintAt]);

  return (
    <WorldInstanceChromeContext.Provider value={instanceChromeStore}>
    <WorldLayerStack>
      <group>
        {instances.map((instance, index) => {
          const meshId = instance.meshId ?? instance.id;
          const meshRecord = meshById.get(meshId);
          const meshData = meshRecord?.data;
          const geometry = geometries.get(meshId);
          const position = instance.position ?? [instance.x ?? index, instance.y ?? 0, instance.z ?? 0];
          const scale = instance.scale ?? WORLD_INSTANCE_UNIT_SCALE;
          const quaternion = worldInstanceQuaternion(instance);
          const isActiveObject = instance.id === selection.activeObjectId || (instance.interactionId != null && instance.interactionId === selection.activeObjectId);
          const componentIds = instance.componentSource ? analyticComponentIdsByInstance.get(instance.id) ?? new Set<number>() : isActiveObject ? selectedComponentIds : new Set<number>();
          const selectedIds = instance.componentSource && isActiveObject && mergedComponentIdsSet ? new Set([...componentIds].filter(id => mergedComponentIdsSet.has(id))) : componentIds;
          return (
            <WorldInstanceNode
              key={instance.id}
              instance={instance}
              previewInstanceSelected={undefined}
              index={index}
              meshRecord={meshRecord}
              meshData={meshData}
              geometry={geometry}
              appearance={meshVisuals.get(meshId)?.appearance}
              borderGeometry={borderGeometries.get(meshId)}
              palette={palette}
              vertexPick={vertexPickByMeshId.get(meshId) ?? null}
              edgeGeometry={edgeGeometryByMeshId.get(meshId) ?? null}
              paintTextureBase64={meshData?.paintTextureBase64}
              position={position as [number, number, number]}
              scale={scale as [number, number, number]}
              quaternion={quaternion}
              targets={targets}
              activeObjectId={selection.activeObjectId ?? undefined}
              selectionMode={selectionMode}
              selectedComponentIds={selectedIds}
              previewComponentIds={previewComponentIds}
              hoveredComponent={hoveredComponent}
              showEdges={selection.showEdges}
              pickEnabled={pickEnabled}
              onPaintAt={onPaintAt}
              paintFromHit={paintFromHit}
              flatShading={instance.smoothShading === false}
              onInstancePointerDown={onInstancePointerDown}
              onInstancePointerMove={handleLocalInstancePointerMove}
              onWorldPick={onWorldPick}
              onComponentHover={onComponentHoverPainted}
              mergeMode={mergeMode}
              faceDragActive={selection.faceDragActive === true}
              onFaceDragStart={onFaceDragStart}
              environmentMaterial={environment?.material}
              environmentShadowEnabled={environment?.shadow?.enabled === true}
              onRootRef={registerInstanceRoot}
            />
          );
        })}
      </group>
      <SceneGumball
        target={selection.gumballTarget}
        config={gumballConfig}
        active={gumballVisible}
        onDraggingChanged={handleGumballDraggingChanged}
        onDragStart={handleGumballDragStart}
        onDrag={handleGumballDrag}
        onDragEnd={handleGumballDragEnd}
      />
    </WorldLayerStack>
    </WorldInstanceChromeContext.Provider>
  );
}
