//#region WorldGumballTransformPreviewStore
export type WorldGumballTransformPreview = {
  readonly sourceId: string;
  readonly transformMode: string | undefined;
  readonly handleKind: GumballHandleKind | null;
  readonly before: GumballPose;
  readonly after: GumballPose;
  readonly instanceIds: readonly string[];
  readonly pivot: readonly [number, number, number];
};

/** 🧲️ Live gumball transform previews keyed by controller so every sibling World3d pane paints the same in-progress move/rotate before the plugin round-trip commits it. */
const worldGumballTransformPreviewByController = new Map<string, WorldGumballTransformPreview>();
const worldGumballTransformPreviewListeners = new Set<() => void>();

function gumballPosesEqual(a: GumballPose, b: GumballPose): boolean {
  return (
    a.position.every((value, index) => Math.abs(value - b.position[index]!) < GUMBALL_TRANSFORM_EPSILON) &&
    a.quaternion.every((value, index) => Math.abs(value - b.quaternion[index]!) < GUMBALL_TRANSFORM_EPSILON) &&
    a.scale.every((value, index) => Math.abs(value - b.scale[index]!) < GUMBALL_TRANSFORM_EPSILON)
  );
}

function worldGumballTransformPreviewsEqual(a: WorldGumballTransformPreview | null | undefined, b: WorldGumballTransformPreview | null | undefined): boolean {
  if (a === b) return true;
  if (!a || !b || a.sourceId !== b.sourceId || a.transformMode !== b.transformMode || a.handleKind !== b.handleKind) return false;
  if (a.instanceIds.length !== b.instanceIds.length || a.instanceIds.some((id, index) => id !== b.instanceIds[index])) return false;
  if (a.pivot.some((value, index) => Math.abs(value - b.pivot[index]!) > GUMBALL_TRANSFORM_EPSILON)) return false;
  return gumballPosesEqual(a.before, b.before) && gumballPosesEqual(a.after, b.after);
}

function notifyWorldGumballTransformPreviewListeners(): void {
  for (const listener of worldGumballTransformPreviewListeners) listener();
}

/** 🧲️ Subscribes a World3d pane to live gumball previews from sibling panes. */
export function subscribeWorldGumballTransformPreview(listener: () => void): () => void {
  worldGumballTransformPreviewListeners.add(listener);
  return () => {
    worldGumballTransformPreviewListeners.delete(listener);
  };
}

/** 🧲️ Returns the live gumball preview for `controllerId`, or `null` outside an in-progress gesture. */
export function getWorldGumballTransformPreview(controllerId: string): WorldGumballTransformPreview | null {
  return worldGumballTransformPreviewByController.get(controllerId) ?? null;
}

/** 🧲️ SSR snapshot for {@link useSyncExternalStore}; gumball gestures never hydrate in progress. */
export function getWorldGumballTransformPreviewServerSnapshot(_controllerId: string): WorldGumballTransformPreview | null {
  return null;
}

/** 🧲️ Publishes an in-progress gumball transform to every World3d pane using the same controller. */
export function setWorldGumballTransformPreview(controllerId: string, preview: WorldGumballTransformPreview | null): void {
  const previous = worldGumballTransformPreviewByController.get(controllerId) ?? null;
  if (worldGumballTransformPreviewsEqual(previous, preview)) return;
  if (preview) worldGumballTransformPreviewByController.set(controllerId, preview);
  else worldGumballTransformPreviewByController.delete(controllerId);
  notifyWorldGumballTransformPreviewListeners();
}

/** 🧲️ Clears a preview only when `sourceId` still owns it, preventing an idle sibling pane from cancelling the active pane's gesture. */
export function clearWorldGumballTransformPreview(controllerId: string, sourceId?: string): void {
  const current = worldGumballTransformPreviewByController.get(controllerId);
  if (!current || (sourceId && current.sourceId !== sourceId)) return;
  setWorldGumballTransformPreview(controllerId, null);
}

/** 🌀 Maps committed vortex markers through an active gumball preview when they belong to a transformed instance — each about
 * its OWN instance's drag-start pose (`owners`, see {@link gumballPreviewOwnedWorldPoint}), so a multi-object turn or scale
 * previews every marker where the release lands it. */
export function worldVorticesWithGumballPreview(
  vortices: readonly WorldVortexRecord[],
  preview: WorldGumballTransformPreview | null,
  owners: ReadonlyMap<string, WorldGumballOwnerPose>,
): readonly WorldVortexRecord[] {
  if (!preview || preview.instanceIds.length === 0) return vortices;
  const selected = new Set(preview.instanceIds);
  return vortices.map((vortex) => {
    const objectId = vortex.objectId ?? vortex.fullId.split(":")[0];
    const owner = objectId ? owners.get(objectId) : undefined;
    if (!objectId || !owner || !selected.has(objectId)) return vortex;
    const position = gumballPreviewOwnedWorldPoint(owner, preview.transformMode, preview.before, preview.after, preview.handleKind, vortex.position);
    const direction = vortex.direction
      ? gumballPreviewOwnedWorldDirection(owner, preview.transformMode, preview.before, preview.after, preview.handleKind, vortex.direction)
      : vortex.direction;
    return direction === vortex.direction && position.every((value, index) => Math.abs(value - vortex.position[index]!) < GUMBALL_TRANSFORM_EPSILON)
      ? vortex
      : { ...vortex, position, direction };
  });
}

/** 🌀 Maps committed attraction endpoints through an active gumball preview when they touch a transformed instance's vortices,
 * each about its own instance's drag-start pose (`owners`) like {@link worldVorticesWithGumballPreview}. */
export function worldAttractionsWithGumballPreview(
  attractions: readonly WorldAttractionRecord[],
  vortices: readonly WorldVortexRecord[],
  preview: WorldGumballTransformPreview | null,
  owners: ReadonlyMap<string, WorldGumballOwnerPose>,
): readonly WorldAttractionRecord[] {
  if (!preview || preview.instanceIds.length === 0) return attractions;
  const selected = new Set(preview.instanceIds);
  const endpointMap = new Map<string, readonly [number, number, number]>();
  for (const vortex of vortices) {
    const objectId = vortex.objectId ?? vortex.fullId.split(":")[0];
    const owner = objectId ? owners.get(objectId) : undefined;
    if (!objectId || !owner || !selected.has(objectId)) continue;
    const key = vortex.position.join(",");
    endpointMap.set(key, gumballPreviewOwnedWorldPoint(owner, preview.transformMode, preview.before, preview.after, preview.handleKind, vortex.position));
  }
  const remap = (point: readonly [number, number, number]) => endpointMap.get(point.join(",")) ?? point;
  return attractions.map((attraction) => {
    const from = remap(attraction.from);
    const to = remap(attraction.to);
    return from === attraction.from && to === attraction.to ? attraction : { ...attraction, from, to };
  });
}
//#endregion WorldGumballTransformPreviewStore

//#region WorldInstanceChromeStore
type WorldInstanceChromeSnapshot = {
  readonly selectedIds: ReadonlySet<string>;
  readonly hoveredId: string | null;
  readonly hoveredKindId: string | null;
  readonly previewInstanceIds: ReadonlySet<string> | null;
};

/** 🎯️ What THIS pane's own raycast has under the pointer: an instance id, `null` for "inside the
 * pane, over nothing", `undefined` for "the pointer is not in this pane" (no local claim). */
export type WorldLocalHoverV1 = string | null | undefined;

/** 🎯️ The instance the hover chrome paints. The pane's own raycast LEADS while the pointer is inside
 * it — that is the value the guest is being told about, one round trip (hundreds of milliseconds
 * through `interactionHover` → reserved job → publication → refresh → commit) before the guest's
 * `hoveredId` echoes it back — so the highlight follows the pointer at raycast speed and the echo
 * only ever confirms it. The guest's lane leads when the pointer is elsewhere: a hover authored by
 * another surface (an outliner row, a remote presence) has nothing local to yield to.
 *
 * 🧭️ Nothing about the guest changes: the same `interactionHover` still reaches it, the same lane
 * comes back, the same selection semantics apply to a click. Only what is PAINTED between the raycast
 * and the echo differs, and it differs toward what the guest will answer. */
export function worldHoverPaintIdV1(local: WorldLocalHoverV1, guest: string | null): string | null {
  return local === undefined ? guest : local;
}

interface WorldInstanceChromeStore {
  subscribe: (listener: () => void) => () => void;
  getSnapshot: () => WorldInstanceChromeSnapshot;
  setSnapshot: (next: WorldInstanceChromeSnapshot) => void;
  /** 🎯️ The pane's raycast result, painted at once and reconciled against the guest echo by
   * {@link worldHoverPaintIdV1}. */
  setLocalHover: (local: WorldLocalHoverV1) => void;
  localHover: () => WorldLocalHoverV1;
  isSelected: (instanceId: string) => boolean;
  isHovered: (instanceId: string) => boolean;
  isHighlighted: (objectKind: string | undefined) => boolean;
  previewSelected: (instanceId: string) => boolean | undefined;
}

function chromeSnapshotsEqual(a: WorldInstanceChromeSnapshot, b: WorldInstanceChromeSnapshot): boolean {
  if (a.hoveredId !== b.hoveredId || a.hoveredKindId !== b.hoveredKindId) return false;
  if (a.previewInstanceIds !== b.previewInstanceIds) {
    if (!a.previewInstanceIds || !b.previewInstanceIds || a.previewInstanceIds.size !== b.previewInstanceIds.size) return false;
    for (const id of a.previewInstanceIds) {
      if (!b.previewInstanceIds.has(id)) return false;
    }
  }
  if (a.selectedIds.size !== b.selectedIds.size) return false;
  for (const id of a.selectedIds) {
    if (!b.selectedIds.has(id)) return false;
  }
  return true;
}

function createWorldInstanceChromeStore(): WorldInstanceChromeStore {
  let snapshot: WorldInstanceChromeSnapshot = {
    selectedIds: new Set(),
    hoveredId: null,
    hoveredKindId: null,
    previewInstanceIds: null,
  };
  let localHover: WorldLocalHoverV1 = undefined;
  const listeners = new Set<() => void>();
  const notify = (): void => {
    for (const listener of listeners) listener();
  };
  return {
    subscribe(listener) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    getSnapshot() {
      return snapshot;
    },
    setSnapshot(next) {
      if (chromeSnapshotsEqual(snapshot, next)) return;
      snapshot = next;
      notify();
    },
    setLocalHover(local) {
      if (local === localHover) return;
      const paintedBefore = worldHoverPaintIdV1(localHover, snapshot.hoveredId);
      localHover = local;
      if (worldHoverPaintIdV1(localHover, snapshot.hoveredId) === paintedBefore) return;
      notify();
    },
    localHover() {
      return localHover;
    },
    isSelected(instanceId) {
      return snapshot.selectedIds.has(instanceId);
    },
    isHovered(instanceId) {
      return worldHoverPaintIdV1(localHover, snapshot.hoveredId) === instanceId;
    },
    isHighlighted(objectKind) {
      return objectKind != null && snapshot.hoveredKindId != null && objectKind === snapshot.hoveredKindId;
    },
    previewSelected(instanceId) {
      if (!snapshot.previewInstanceIds) return undefined;
      return snapshot.previewInstanceIds.has(instanceId);
    },
  };
}

const WorldInstanceChromeContext = reactHostPort.createContext<WorldInstanceChromeStore | null>(null);

function useWorldInstanceChromeStore(): WorldInstanceChromeStore {
  const store = reactHostPort.useContext(WorldInstanceChromeContext);
  if (!store) throw new Error("World instance chrome hooks must render inside WorldInstancesLayer");
  return store;
}

function useWorldInstanceChrome(
  instanceId: string,
  objectKind: string | undefined,
): {
  readonly selected: boolean;
  readonly hovered: boolean;
  readonly highlighted: boolean;
  readonly previewSelected: boolean | undefined;
} {
  const store = useWorldInstanceChromeStore();
  const selected = reactHostPort.useSyncExternalStore(store.subscribe, () => store.isSelected(instanceId), () => false);
  const hovered = reactHostPort.useSyncExternalStore(store.subscribe, () => store.isHovered(instanceId), () => false);
  const highlighted = reactHostPort.useSyncExternalStore(store.subscribe, () => store.isHighlighted(objectKind), () => false);
  const previewSelected = reactHostPort.useSyncExternalStore(store.subscribe, () => store.previewSelected(instanceId), () => undefined);
  return { selected, hovered, highlighted, previewSelected };
}

//#endregion WorldInstanceChromeStore

/** 🖱️➡️ Signed distance along `axis` (unit vector) from `origin` to the point on that line closest to the
 * camera ray through the current pointer position — the standard closest-point-between-two-lines
 * construction, used so a face-normal drag tracks naturally instead of needing a ground/tangent-plane
 * intersection (which is undefined for motion parallel to the plane, i.e. exactly along the normal). */
function axisDragParam(clientX: number, clientY: number, hostRect: DOMRect, camera: ThreeCamera, origin: readonly [number, number, number], axis: readonly [number, number, number]): number | null {
  const ndcX = ((clientX - hostRect.left) / hostRect.width) * 2 - 1;
  const ndcY = -(((clientY - hostRect.top) / hostRect.height) * 2 - 1);
  const ray = worldRayFromNdc(ndcX, ndcY, camera);
  if (!ray) return null;
  const axisOrigin = new Vector3(origin[0], origin[1], origin[2]);
  const axisDirection = new Vector3(axis[0], axis[1], axis[2]).normalize();
  const originDelta = ray.origin.clone().sub(axisOrigin);
  const a = ray.direction.dot(ray.direction);
  const b = ray.direction.dot(axisDirection);
  const c = axisDirection.dot(axisDirection);
  const d = ray.direction.dot(originDelta);
  const e = axisDirection.dot(originDelta);
  const denominator = a * c - b * b;
  if (Math.abs(denominator) < 1e-9) return null;
  return (a * e - b * d) / denominator;
}

/** 🪪️ Element id of one world surface's projection pane. A world surface is mounted once per OPEN WINDOW
 * INSTANCE of its kind (`WindowInstanceIdContext`), and {@link Pane} renders its `id` on the pane root plus two
 * derived control ids (`…pane.fold`, `…pane.foldControl`), so the bare `framework.worldOrbit.projection` it used
 * to carry put three DUPLICATE DOM ids in the document per extra pane — invalid HTML, and it makes the pane
 * unaddressable through `<label for>`, `aria-labelledby` and any automation. The instance segment is the same
 * camelCase {@link childElementId} convention the window element ids use (`…projection.puzzle3dMainPerspective`). */
export function world3dProjectionPaneElementId(windowElementSegment: string): string {
  return childElementId("framework.worldOrbit.projection", windowElementSegment);
}

/** 🔀️ Portals the world's projection-kind switch into the enclosing window's pane host (see `usePaneSlot`), defaulting to bottom-right under the navigation cube — the cube sits above the folded chrome and the unfolded pane grows over it. Falls back to a local overlay when no pane host is mounted yet (or outside one). */
export function WorldOrbitProjectionSwitchPane({ spec, onSpecChange, windowElementSegment }: { readonly spec: WorldProjectionSpec; readonly onSpecChange: (spec: WorldProjectionSpec) => void; readonly windowElementSegment: string }) {
  const [anchor, setAnchor] = useState<Anchor>("bottom-right");
  const [folded, setFolded] = useState(true);
  const projectionLabel = useLabel("ui.host.projection");
  const paneId = world3dProjectionPaneElementId(windowElementSegment);
  const pane = (
    <Pane
      id={paneId}
      anchor={anchor}
      onAnchorChange={setAnchor}
      folded={folded}
      onFoldToggle={() => setFolded((value) => !value)}
      icon={worldProjectionSpecIconId(spec) as IconName}
      label={projectionLabel}
      bodyClassName={windowMeasuresBodyClass}
      stackDataAttrs={{ "data-level": "pane" }}
      dimWhenOpen
    >
      <WorldProjectionKindSwitch id={paneId} spec={spec} onSpecChange={onSpecChange} />
    </Pane>
  );
  const portaled = usePaneSlot(pane);
  if (portaled) return portaled;
  return (
    <div className="pointer-events-none absolute inset-0" data-slot="world-orbit-projection-switch-fallback" data-world-projection-kind-switch-host="">
      {pane}
    </div>
  );
}

//#region WorldWindowInstance
/** 🪪️ Identifies which window *pane* (not just which window *kind*) a `ComponentSceneHost` is
 * mounted for — every window kind's `UiNode` is shared verbatim across all of its open instances, so a
 * host can't otherwise tell which pane it is; provided per-pane around each `<InterpretedUiNode>` call. */
export const WindowInstanceIdContext = createContext<string | null>(null);

export type World3dRetainedViewportV1 = Readonly<{
  camera: WorldParsedCameraState | null;
  viewportOwned: boolean;
  userMovedFitRevision: number | null;
  detachEpoch: number;
  projectionContentFrameSeeded: boolean;
  lastDispatchedCamera: WorldCameraState | null;
  observedSceneCameraJson: string;
  sceneCameraAttachJson: string;
  pendingProjectionSpec: WorldProjectionSpec | null;
}>;

/** 📷️ Shell-session owner of live per-window world viewports. */
export class World3dWindowViewStoreV1 {
  readonly #views = new Map<string, World3dRetainedViewportV1>();
  #owner: string | null = null;

  admitOwner(owner: string | null): void {
    if (this.#owner === owner) return;
    this.#owner = owner;
    this.#views.clear();
  }

  read(windowId: string | null): World3dRetainedViewportV1 | null {
    return windowId ? (this.#views.get(windowId) ?? null) : null;
  }

  write(windowId: string | null, viewport: World3dRetainedViewportV1): void {
    if (windowId) this.#views.set(windowId, viewport);
  }

  retire(windowId: string | null): void {
    if (windowId) this.#views.delete(windowId);
  }
}

/** 🪪️ Keeps independently-lived primary and spawned program viewport owners apart. */
export class World3dWindowViewRegistryV1 {
  readonly #stores = new Map<string, World3dWindowViewStoreV1>();

  scope(owner: string): World3dWindowViewStoreV1 {
    const retained = this.#stores.get(owner);
    if (retained) return retained;
    const created = new World3dWindowViewStoreV1();
    created.admitOwner(owner);
    this.#stores.set(owner, created);
    return created;
  }

  retireOwner(owner: string | null): void {
    if (owner) this.#stores.delete(owner);
  }

  retireWindow(windowId: string | null): void {
    for (const store of this.#stores.values()) store.retire(windowId);
  }
}

/** 🐚️ The current shell session's live world viewport owner. */
export const World3dWindowViewStoreContext = createContext<World3dWindowViewStoreV1 | null>(null);

/** 🪟️ One-shot initial camera pose, keyed by window instance id, consumed by {@link World3dHost} on
 * mount and then discarded — the side-channel a Display "Windows" drag-and-drop template uses to seed a
 * freshly-opened pane's projection (dragging "Top" opens a pane that starts in the Top view, etc.). */
const pendingWorldProjectionByWindowId = new Map<string, WorldProjectionSpec>();

/** 🪟️ Registers `spec` to be consumed once by the next {@link World3dHost} mounted for `windowId`. */
export function registerPendingWorldProjection(windowId: string, spec: WorldProjectionSpec): void {
  pendingWorldProjectionByWindowId.set(windowId, spec);
}

/** 🪟️ Peeks the sticky initial projection for `windowId` — kept until the pane is closed so React
 * Strict Mode's mount→unmount→remount pass still seeds both Top and Perspective (take-on-read / clear-on-apply
 * left the second mount on the shared scene camera and empty transparent canvases). */
function peekPendingWorldProjection(windowId: string | null): WorldProjectionSpec | null {
  if (!windowId) return null;
  return pendingWorldProjectionByWindowId.get(windowId) ?? null;
}

/** 🪟️ Drops the initial projection seed when a pane is closed (not after first apply). */
export function clearPendingWorldProjection(windowId: string | null): void {
  if (!windowId) return;
  pendingWorldProjectionByWindowId.delete(windowId);
}

/** 🪦️ Retires projection seeds owned by a session that is leaving the shell. */
export function clearPendingWorldProjections(windowIds: readonly string[]): void {
  for (const windowId of windowIds) pendingWorldProjectionByWindowId.delete(windowId);
}
//#endregion WorldWindowInstance

//#region 🎯️WorldInteractionDomain
/** 🎯️ Granularity a plain world instance hit reports when the scene declares no
 * `domainGranularityId` — matches the node graph's own port granularity, which is what an
 * instance standing for one output channel resolves to. */
export const WORLD3D_DEFAULT_INTERACTION_GRANULARITY = "handle";

/** 🖱️ Mirrors `nodeGraphHoverActionArgs` (`NodeGraph/🟦️.tsx`) for a world window bound to a
 * framework interaction domain (`scene.domainId`), reporting the scene's own
 * `domainGranularityId` — the same shape a `domain_id`-aware `interactionHover` handler expects. */
export function world3dHoverActionArgs(domainId: string, granularity: string, id: string | null | undefined) {
  const targets = id ? [{ granularity, id }] : [];
  return { domainId, channel: "pointer", targets: JSON.stringify(targets) };
}

/** ✨ Alt+right-click opens suggestions only when a vortex marker is already hovered. */
export function world3dSuggestionsGestureArmed(altKey: boolean, hoveredVortexFullId: string | null | undefined): boolean {
  return Boolean(altKey && hoveredVortexFullId);
}

/** ✨ Playwright/macOS often omit `event.altKey` on reconstructed pointer events — track the key. */
export function world3dSuggestionsAltHeld(eventAltKey: boolean, altHeld: boolean): boolean {
  return Boolean(eventAltKey || altHeld);
}

/** ✨ Guest `interactionHover` may stay null after a spawn-admit miss — keep the local marker hover for Alt+right-click. */
export function world3dRetainLocalVortexHover(local: string | null | undefined, guest: string | null | undefined): string | null {
  return guest || local || null;
}

/** ✨ Alt+right-click is the suggestions gesture — consume contextmenu so workspace chrome cannot steal it. */
export function world3dSuggestionsGestureConsumesContextMenu(altKey: boolean): boolean {
  return altKey;
}

/** ✨ Chrome overlays steal bubbling button=2 before orbit's canvas listener — window capture over the host is the route. */
export function world3dSuggestionsRightDownRoutesOnWindowCapture(button: number, overHost: boolean): boolean {
  return button === 2 && overHost;
}

type World3dSuggestionsRightDownRoute = {
  readonly host: () => HTMLElement | null;
  readonly handle: (event: PointerEvent) => boolean;
};
const world3dSuggestionsRightDownRoutes = new Set<World3dSuggestionsRightDownRoute>();

function world3dSuggestionsEventOverHost(node: HTMLElement | null, clientX: number, clientY: number): boolean {
  if (!node) return false;
  const rects = [node.getBoundingClientRect(), ...Array.from(node.querySelectorAll("canvas")).map((canvas) => canvas.getBoundingClientRect())];
  return rects.some((rect) => rect.width > 1 && rect.height > 1 && clientPointOverHost(clientX, clientY, rect));
}

function world3dSuggestionsDispatchWindowRightDown(event: PointerEvent): void {
  if (event.button !== 2) return;
  for (const route of world3dSuggestionsRightDownRoutes) {
    const overHost = world3dSuggestionsEventOverHost(route.host(), event.clientX, event.clientY);
    if (!world3dSuggestionsRightDownRoutesOnWindowCapture(event.button, overHost)) continue;
    if (route.handle(event) !== false) continue;
    event.preventDefault();
    event.stopPropagation();
    return;
  }
}

// 🧭️ `globalThis.` because this file imports React's synthetic `MouseEvent`/`DragEvent` for JSX props,
// which shadow the globals — and a real `window.addEventListener` listener is handed the DOM event.
function world3dSuggestionsDispatchWindowContextMenu(event: globalThis.MouseEvent): void {
  for (const route of world3dSuggestionsRightDownRoutes) {
    if (!world3dSuggestionsEventOverHost(route.host(), event.clientX, event.clientY)) continue;
    const asPointer = event as unknown as PointerEvent;
    if (route.handle(asPointer) !== false) continue;
    event.preventDefault();
    event.stopPropagation();
    return;
  }
}

if (typeof window !== "undefined") {
  window.addEventListener("pointerdown", world3dSuggestionsDispatchWindowRightDown, true);
  window.addEventListener("contextmenu", world3dSuggestionsDispatchWindowContextMenu, true);
}

/** 🖱️ Mirrors `nodeGraphSelectionActionArgs` for a world window bound to a framework interaction
 * domain — `merge` is passed through as already resolved at the call site (marquee/click modifier
 * state), not recomputed here. */

/** 🖱️ Instance picks join a scene interaction domain only when the instance names a topology id. */
export function world3dInstancePickUsesInteractionDomain(record: { readonly interactionId?: string } | undefined): boolean {
  return typeof record?.interactionId === "string" && record.interactionId.length > 0;
}

/** 🖱️ A selection is a SET of topology ids, so the target list this builds is one: the same id
 * can be handed in twice (several rendered instances of one channel, a pick batch the caller did not
 * run through {@link interactionTargetsForInstances}), and a `Select` must be idempotent per id —
 * the host never emits a duplicate target. Live defect 2026-09-12 (ticket
 * 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️selection-dedupe-2026-09-12.md`): the guest republished one
 * picked id twice, and only a set on BOTH sides makes that unrepresentable. */
/** 🎯️ `merge` is a `MergeMode` — the ONE vocabulary of `🕹️interaction/🧬️schema/🔣️.json`, put on the
 * wire verbatim. A host must NOT translate it: the framework's `parse_merge_mode` accepts exactly
 * those five words and faults on anything else. */
export function world3dSelectionActionArgs(domainId: string, granularity: string, ids: readonly string[], merge: MergeMode) {
  const targets = [...new Set(ids)].map((id) => ({ granularity, id }));
  return { domainId, targets: JSON.stringify(targets), merge, method: "pick" };
}

/** 🎯️ Resolves rendered instance ids onto the interaction targets they stand for, deduplicated and
 * order-preserving — several instances can share one target (procedural3d renders one instance per
 * geometry item of a channel, all of which resolve to that channel's port). */
export function interactionTargetsForInstances(instances: readonly WorldInstanceRecord[], ids: readonly string[]): readonly string[] {
  const seen = new Set<string>();
  const targets: string[] = [];
  for (const id of ids) {
    const target = instances.find((entry) => entry.id === id)?.interactionId ?? id;
    if (seen.has(target)) continue;
    seen.add(target);
    targets.push(target);
  }
  return targets;
}

/** 🎯️ The `{ granularity, id }` interaction target one rendered instance stands for — the record's own
 * `interactionGranularityId`/`interactionId` win, else the scene's default granularity and the id itself. */
export function world3dInstanceInteractionTarget(instances: readonly WorldInstanceRecord[], id: string, defaultGranularity: string): { readonly granularity: string; readonly id: string } {
  const record = instances.find((entry) => entry.id === id);
  return { granularity: record?.interactionGranularityId ?? defaultGranularity, id: record?.interactionId ?? id };
}

/** 🎯️ Every rendered instance id resolved onto its interaction target, deduplicated and order-preserving,
 * each under its OWN granularity — the marquee's shape of {@link interactionTargetsForInstances}. */
export function world3dInstanceInteractionTargets(instances: readonly WorldInstanceRecord[], ids: readonly string[], defaultGranularity: string): readonly { readonly granularity: string; readonly id: string }[] {
  const seen = new Set<string>();
  const targets: { readonly granularity: string; readonly id: string }[] = [];
  for (const id of ids) {
    const target = world3dInstanceInteractionTarget(instances, id, defaultGranularity);
    const key = `${target.granularity}\u0000${target.id}`;
    if (seen.has(key)) continue;
    seen.add(key);
    targets.push(target);
  }
  return targets;
}

/** 🎯️ The interaction target of one mesh COMPONENT (face/edge/vertex) of a rendered instance under a
 * domain: `<objectInteractionId>.<granularity>.<componentId>`, the object's own target id extended by the
 * component address (the lowpoly "mesh" domain's `lowpoly-document.<objectId>.<granularity>.<id>` rows). */
export function world3dComponentInteractionTarget(instances: readonly WorldInstanceRecord[], meshes: readonly WorldMeshRecord[], objectId: string, granularity: string, componentId: number): { readonly granularity: string; readonly id: string } | undefined {
  const record = instances.find((entry) => entry.id === objectId) ?? instances.find((entry) => entry.interactionId === objectId);
  const id = `${record?.interactionId ?? objectId}.${granularity}.${componentId}`;
  const source = record?.componentSource;
  if (!source) return { granularity, id };
  if (!Number.isInteger(componentId) || componentId < 0 || !["vertex", "edge", "face"].includes(granularity) || !/^[0-9a-f]{64}$/.test(source.handle) || !/^[0-9a-f]{64}$/.test(source.revision)) return undefined;
  const references = meshes.find(mesh => mesh.id === record?.meshId)?.data?.componentReferences?.[granularity];
  const label = references?.[componentId];
  if (!label || !/^[1-9][0-9]{0,19}$/.test(label) || BigInt(label) > 18446744073709551615n || references!.filter(value => value === label).length !== 1) return undefined;
  return { granularity, id: `${id}~${source.handle}~${label}~${source.revision}` };
}

/** 🎯️ `interactionSelect` args over already-resolved `{ granularity, id }` targets. */
export function world3dSelectionTargetsActionArgs(domainId: string, targets: readonly { readonly granularity: string; readonly id: string }[], merge: MergeMode, method: "pick" | "rectangle" | "lasso" = "pick") {
  return { domainId, targets: JSON.stringify(targets), merge, method };
}

/** 🧿️ The pickable non-instance layers of a `World3dScene`, each named after the scene field it is
 * parsed from (`vorticesJson`, `attractionsJson`, `targetVolumesJson`, `referencesJson`). */
export type World3dMarkerLayer = "vortex" | "attraction" | "targetVolume" | "reference";

/** 🧿️ Granularity a marker hit reports when its scene record declares no `interactionGranularityId`
 * — the layer's own name, the same way {@link WORLD3D_DEFAULT_INTERACTION_GRANULARITY} names the
 * instance layer's default. Keeps the host free of any per-app granularity vocabulary: an app that
 * calls its marker rows something else overrides it per record from the scene JSON. */
export const WORLD3D_DEFAULT_MARKER_GRANULARITY: Readonly<Record<World3dMarkerLayer, string>> = {
  vortex: "vortex",
  attraction: "attraction",
  targetVolume: "targetVolume",
  reference: "reference",
};

/** 🧿️ What every pickable marker record may carry to redirect its own hit — both read straight off
 * the scene JSON, so which interaction target a marker stands for is the plugin's statement, never
 * the host's guess. */
export type World3dMarkerInteractionFields = {
  readonly interactionId?: string;
  readonly interactionGranularityId?: string;
};

/** 🧿️ Resolves the `{ granularity, id }` interaction target one marker hit stands for — the record's
 * own scene-JSON fields win, else the record's own id at its layer's default granularity. */
export function world3dMarkerInteractionTarget(layer: World3dMarkerLayer, id: string, record?: World3dMarkerInteractionFields): { readonly granularity: string; readonly id: string } {
  return { granularity: record?.interactionGranularityId ?? WORLD3D_DEFAULT_MARKER_GRANULARITY[layer], id: record?.interactionId ?? id };
}
//#endregion 🎯️WorldInteractionDomain

//#region World3dHost
/** 🚚️ `node.world3d` arrives ASSEMBLED. Its payload fields (`instancesJson`, `vorticesJson`, … — see
 * `WORLD3D_SCENE_LANES`) no longer ride inside the surface doc's 32 KiB `UiFixedBytes` blob, which
 * cannot page and refused a 57 KB Nakagin world outright; each is published as its own retained,
 * individually paged text carrier beside the surface node and reattached by the Interpreter's
 * `PagedSurfaceView` before this host ever sees it (ticket 26/09/02 wave P). Every `*Json` field is
 * therefore still a plain string here, and the per-lane `useMemo`s below stay the incremental seam:
 * a lane whose content did not change keeps its identical string, so its parse never re-runs. */
export function World3dHost({ node, onAction, requestContextMenu }: ComponentSceneHostProps) {
  const scene = node.world3d;
  // 🪟️ Non-empty only — an empty-string `domainId` (never emitted by the Rust side, but defensive
  // against a hand-authored fixture) must fall back to the plugin-private action pathway below.
  const interactionDomainId = scene?.domainId ? scene.domainId : undefined;
  const interactionGranularity = scene?.domainGranularityId ? scene.domainGranularityId : WORLD3D_DEFAULT_INTERACTION_GRANULARITY;
  // 🐚️ Optional — this host is also unit-tested standalone, outside any `ShellScopeProvider`.
  const shellScope = useShellScopeOptional();
  // 🐚️ Read as reactive state (not `shellScope.selection.get()` inline at each use) because this value
  // is consumed inside `<Canvas>` r3f subtrees (`WorldInstancesLayer`) via a prop, not context — R3F
  // primitives aren't guaranteed to re-render just because an *outer* DOM component's context changed,
  // so the toolbar's mode toggle needs an explicit subscription to actually propagate.
  const [persistentSelectionMode, setPersistentSelectionMode] = useState<MergeMode>(() => shellScope?.selection.get() ?? "replace");
  useEffect(() => {
    if (!shellScope) return;
    return shellScope.selection.subscribe(() => setPersistentSelectionMode(shellScope.selection.get()));
  }, [shellScope]);
  const windowInstanceId = useContext(WindowInstanceIdContext);
  const windowViewStore = useContext(World3dWindowViewStoreContext);
  const setWindowTitle = useContext(SetWindowTitleContext);
  const setWindowIcon = useContext(SetWindowIconContext);
  const emptySceneLabel = useLabel("ui.host.emptyScene");
  const meshStylePalette = useMeshStylePalette();
  const colors = useMemo(() => semanticColorsFromPalette(meshStylePalette), [meshStylePalette]);
  const sceneCameraJson = scene?.cameraJson ?? "{}";
  const parsedCamera = useMemo(() => parseCameraState(sceneCameraJson), [sceneCameraJson]);
  // 🚚️ B44: the retained instance set advances by the producer's own per-object delta when it can, so a
  // pose edit on a 180-object document substitutes the moved records by id instead of re-parsing 55 KiB.
  const instanceResidencyRef = useRef<WorldInstanceResidencyV1 | null>(null);
  const instances = useMemo(() => {
    const advanced = advanceWorldInstanceResidency(instanceResidencyRef.current, scene?.instancesJson ?? "[]", scene?.instancesDeltaJson ?? null);
    instanceResidencyRef.current = advanced;
    return advanced.records as WorldInstanceRecord[];
  }, [scene?.instancesJson, scene?.instancesDeltaJson]);
  const references = useMemo(() => parseJsonArray<WorldReferenceRecord>(scene?.referencesJson), [scene?.referencesJson]);
  const sceneCamera = useMemo(() => {
    if (sceneCameraJson.includes('"position"')) return parsedCamera;
    return instances.length > 0 ? autofitCameraFromInstances(instances) : parsedCamera;
  }, [instances, parsedCamera, sceneCameraJson]);
  const contentBounds = useMemo(() => worldSceneContentBounds(world3dFramingInstances(instances), references), [instances, references]);
  const [retainedViewport] = useState(() => windowViewStore?.read(windowInstanceId) ?? null);
  const pendingProjectionSpecRef = useRef<WorldProjectionSpec | null>(null);
  const [viewportCamera, setViewportCamera] = useState<WorldParsedCameraState | null>(() => {
    if (retainedViewport) return retainedViewport.camera;
    const pendingSpec = peekPendingWorldProjection(windowInstanceId);
    if (!pendingSpec) return null;
    pendingProjectionSpecRef.current = pendingSpec;
    return seedPendingWorldProjectionCamera(pendingSpec, sceneCamera, instances, references);
  });
  const [projectionFramePending, setProjectionFramePending] = useState(() => retainedViewport === null && pendingProjectionSpecRef.current !== null);
  const [viewportOwned, setViewportOwned] = useState(retainedViewport?.viewportOwned ?? false);
  const [cameraNavigating, setCameraNavigating] = useState(false);
  /** 🔒️ The fit revision the USER last moved this camera on. While it names the live revision the auto-fit
